// SVG 1 — UNCLOS TIMELINE
// ══════════════════════════════════════
function UNCLOSTimelineSVG({ lang }) {
  const [sel, setSel] = useState(null);
  const events = [
    { year:"1958", icon:"📜", color:C.orange,
      label:{fr:"Conventions de Genève",en:"Geneva Conventions",es:"Convenciones de Ginebra",pt:"Convenções de Genebra"},
      desc:{fr:"4 conventions séparées de Genève (1958) :\n• Mer territoriale et zone contiguë\n• Haute mer\n• Plateau continental\n• Pêche et conservation ressources\n\nLimitations : pas de ZEE · limites floues · conflits d'interprétation\nNécessité d'une convention unifiée → UNCLOS I (1958) puis UNCLOS III",en:"4 separate Geneva Conventions (1958):\n• Territorial sea and contiguous zone\n• High seas\n• Continental shelf\n• Fishing and conservation of resources\n\nLimitations: no EEZ · unclear limits · interpretation conflicts\nNeed for unified convention → UNCLOS I (1958) then UNCLOS III",es:"4 convenios separados de Ginebra (1958):\n• Mar territorial y zona contigua\n• Alta mar\n• Plataforma continental\n• Pesca y conservación de recursos\n\nLimitaciones: sin ZEE · límites poco claros · conflictos de interpretación\nNecesidad de convenio unificado → CONVEMAR I (1958) luego III",pt:"4 convenções separadas de Genebra (1958):\n• Mar territorial e zona contígua\n• Alto mar\n• Plataforma continental\n• Pesca e conservação de recursos\n\nLimitações: sem ZEE · limites vagos · conflitos de interpretação\nNecessidade de convenção unificada → UNCLOS I (1958) depois III"}},
    { year:"1973", icon:"🌍", color:C.blue2,
      label:{fr:"Conférence UNCLOS III",en:"UNCLOS III Conference",es:"Conferencia CONVEMAR III",pt:"Conferência UNCLOS III"},
      desc:{fr:"Conférence UNCLOS III — New York et Genève\n1973 → 1982 : 9 ans de négociations\n150+ États participants\nPrincipaux débats :\n→ Largeur mer territoriale (3 vs 12 milles ?)\n→ Création de la ZEE (concept nouveau)\n→ Régime de la Zone internationale des fonds marins\n→ Règlement obligatoire des différends\nResultat : UNCLOS = 320 articles + 9 annexes",en:"UNCLOS III Conference — New York and Geneva\n1973 → 1982: 9 years of negotiations\n150+ participating states\nMain debates:\n→ Width of territorial sea (3 vs 12 miles?)\n→ Creation of EEZ (new concept)\n→ International Seabed Area regime\n→ Mandatory dispute settlement\nResult: UNCLOS = 320 articles + 9 annexes",es:"Conferencia CONVEMAR III — Nueva York y Ginebra\n1973 → 1982: 9 años de negociaciones\nMás de 150 Estados participantes\nPrincipales debates:\n→ Anchura del mar territorial (¿3 o 12 millas?)\n→ Creación de la ZEE (concepto nuevo)\n→ Régimen de la Zona internacional de fondos marinos\n→ Solución obligatoria de controversias",pt:"Conferência UNCLOS III — Nova Iorque e Genebra\n1973 → 1982: 9 anos de negociações\n150+ Estados participantes\nPrincipais debates:\n→ Largura do mar territorial (3 vs 12 milhas?)\n→ Criação da ZEE (conceito novo)\n→ Regime da Área Internacional dos Fundos Marinhos\n→ Solução obrigatória de controvérsias"}},
    { year:"1982", icon:"✍️", color:C.gold2,
      label:{fr:"Adoption Montego Bay",en:"Adopted at Montego Bay",es:"Adopción Montego Bay",pt:"Adoção Montego Bay"},
      desc:{fr:"Adoption de UNCLOS — 10 décembre 1982\nMontego Bay, Jamaïque\n130 États signataires initiaux\nSurnommée 'Constitution maritime mondiale'\n\nNON-RATIFICATION USA :\nLes États-Unis n'ont PAS ratifié UNCLOS\n(désaccord sur la Zone internationale des fonds marins)\nMais appliquent la plupart des dispositions comme droit coutumier\n→ Paradoxe juridique majeur",en:"Adoption of UNCLOS — December 10, 1982\nMontego Bay, Jamaica\n130 initial signatory states\nNicknamed 'Maritime World Constitution'\n\nUS NON-RATIFICATION:\nUSA has NOT ratified UNCLOS\n(disagreement on International Seabed Area)\nBut applies most provisions as customary law\n→ Major legal paradox",es:"Adopción de CONVEMAR — 10 de diciembre de 1982\nMontego Bay, Jamaica\n130 estados signatarios iniciales\nApodada 'Constitución Marítima Mundial'\n\nNO RATIFICACIÓN EE.UU.:\nEEUU NO ha ratificado CONVEMAR\n(desacuerdo sobre la Zona internacional de fondos marinos)\nPero aplica la mayoría de disposiciones como derecho consuetudinario",pt:"Adoção da UNCLOS — 10 de dezembro de 1982\nMontego Bay, Jamaica\n130 estados signatários iniciais\nIdadada 'Constituição Marítima Mundial'\n\nNÃO RATIFICAÇÃO EUA:\nOS EUA NÃO ratificaram a UNCLOS\n(desacordo sobre a Área Internacional dos Fundos Marinhos)\nMas aplicam a maioria das disposições como direito consuetudinário"}},
    { year:"1994", icon:"⚓", color:C.green,
      label:{fr:"Entrée en vigueur",en:"Entry into force",es:"Entrada en vigor",pt:"Entrada em vigor"},
      desc:{fr:"UNCLOS entre en vigueur — 16 novembre 1994\n(12 mois après la 60ème ratification)\nCréation du TIDM (Tribunal International du Droit de la Mer)\nSiège : Hambourg, Allemagne\nCréation de l'Autorité internationale des fonds marins\nSiège : Kingston, Jamaïque\n→ UNCLOS = droit international contraignant pour 168 États",en:"UNCLOS enters into force — November 16, 1994\n(12 months after 60th ratification)\nCreation of ITLOS (International Tribunal for the Law of the Sea)\nSeat: Hamburg, Germany\nCreation of International Seabed Authority\nSeat: Kingston, Jamaica\n→ UNCLOS = binding international law for 168 states",es:"CONVEMAR entra en vigor — 16 de noviembre de 1994\n(12 meses tras la 60ª ratificación)\nCreación del TIDM (Tribunal Internacional del Derecho del Mar)\nSede: Hamburgo, Alemania\nCreación de la Autoridad Internacional de los Fondos Marinos\nSede: Kingston, Jamaica",pt:"UNCLOS entra em vigor — 16 de novembro de 1994\n(12 meses após a 60ª ratificação)\nCriação do TIDM (Tribunal Internacional do Direito do Mar)\nSede: Hamburgo, Alemanha\nCriação da Autoridade Internacional dos Fundos Marinhos\nSede: Kingston, Jamaica"},},
    { year:"2016", icon:"⚖️", color:C.red,
      label:{fr:"Philippines vs Chine",en:"Philippines vs China",es:"Filipinas vs China",pt:"Filipinas vs China"},
      desc:{fr:"Sentence arbitrale Philippines vs Chine — 12 juillet 2016\nTribunal Arbitral (Annexe VII UNCLOS)\nSujet : revendications chinoises en Mer de Chine du Sud\n(Ligne des 9 tirets)\n\nDÉCISION :\n→ La 'Ligne des 9 tirets' n'a pas de base légale en UNCLOS\n→ Chine a violé les droits de la ZEE des Philippines\n→ Chine refuse d'appliquer la sentence\n→ Tension droit international vs puissance nationale\n→ Démontre limites du système UNCLOS",en:"Philippines v. China Arbitral Award — July 12, 2016\nArbitral Tribunal (UNCLOS Annex VII)\nSubject: Chinese claims in South China Sea\n(9-dash line)\n\nDECISION:\n→ The '9-dash line' has no legal basis in UNCLOS\n→ China violated Philippines' EEZ rights\n→ China refuses to implement the award\n→ Tension international law vs national power\n→ Demonstrates limits of UNCLOS system",es:"Laudo arbitral Filipinas vs China — 12 julio 2016\nTribunal Arbitral (Anexo VII CONVEMAR)\nAsunto: reclamaciones chinas en el Mar de China Meridional\n(Línea de los 9 puntos)\n\nDECISIÓN:\n→ La 'Línea de los 9 puntos' no tiene base legal en CONVEMAR\n→ China violó los derechos de la ZEE de Filipinas\n→ China se niega a aplicar el laudo",pt:"Sentença arbitral Filipinas vs China — 12 julho 2016\nTribunal Arbitral (Anexo VII UNCLOS)\nAssunto: reivindicações chinesas no Mar do Sul da China\n(Linha dos 9 traços)\n\nDECISÃO:\n→ A 'Linha dos 9 traços' não tem base legal na UNCLOS\n→ China violou os direitos da ZEE das Filipinas\n→ China recusa implementar a sentença"},},
  ];
  return (
    <div>
      <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:10}}>
        {events.map((e,i)=>(
          <button key={i} onClick={()=>setSel(sel===i?null:i)} style={{
            flex:"1 1 28%",padding:"8px 4px",borderRadius:10,cursor:"pointer",textAlign:"center",
            background:sel===i?`${e.color}22`:"rgba(255,255,255,0.04)",
            border:`1.5px solid ${sel===i?e.color:"rgba(255,255,255,0.08)"}`,
          }}>
            <div style={{fontSize:16}}>{e.icon}</div>
            <div style={{fontSize:9,color:sel===i?e.color:C.muted,fontWeight:700,marginTop:2}}>{e.year}</div>
            <div style={{fontSize:7,color:sel===i?e.color:C.muted,lineHeight:1.2}}>{(e.label[lang]||e.label.fr).split(' ').slice(0,2).join(' ')}</div>
          </button>
        ))}
      </div>
      {sel!==null&&<div style={{padding:"12px",borderRadius:14,background:`${events[sel].color}15`,border:`1px solid ${events[sel].color}44`,animation:"fadeUp 0.3s ease"}}>
        <div style={{fontSize:13,fontWeight:700,color:events[sel].color,marginBottom:6}}>{events[sel].icon} {events[sel].year} — {events[sel].label[lang]||events[sel].label.fr}</div>
        <div style={{fontSize:11,color:C.white,lineHeight:1.6,whiteSpace:"pre-line"}}>{events[sel].desc[lang]||events[sel].desc.fr}</div>
      </div>}
    </div>
  );
}

