// SVG 2 — MARITIME ZONES INTERACTIVE
// ══════════════════════════════════════
function MaritimeZonesSVG({ lang }) {
  const [sel, setSel] = useState(null);
  const zones = [
    { id:"internal", nm:0, width:8, color:C.red, icon:"🏭",
      label:{fr:"Eaux intérieures",en:"Internal waters",es:"Aguas interiores",pt:"Águas interiores"},
      limit:{fr:"0 mille",en:"0 miles",es:"0 millas",pt:"0 milhas"},
      rights:{fr:"SOUVERAINETÉ TOTALE\n→ Ports · rivières · rades\n→ Aucun droit de passage\n→ État côtier = maître absolu\n→ Navires étrangers = accès sur autorisation\n→ COLREG + droit national s'appliquent\n→ Réglementation portuaire obligatoire",en:"TOTAL SOVEREIGNTY\n→ Ports · rivers · roadsteads\n→ No right of passage\n→ Coastal state = absolute master\n→ Foreign vessels = access by authorization\n→ COLREG + national law apply\n→ Mandatory port regulations",es:"SOBERANÍA TOTAL\n→ Puertos · ríos · radas\n→ Sin derecho de paso\n→ Estado ribereño = amo absoluto\n→ Buques extranjeros = acceso con autorización\n→ COLREG + derecho nacional se aplican",pt:"SOBERANIA TOTAL\n→ Portos · rios · ancoradouros\n→ Sem direito de passagem\n→ Estado costeiro = senhor absoluto\n→ Navios estrangeiros = acesso mediante autorização\n→ COLREG + direito nacional aplicam-se"}},
    { id:"territorial", nm:12, width:16, color:C.orange, icon:"🚩",
      label:{fr:"Mer territoriale",en:"Territorial sea",es:"Mar territorial",pt:"Mar territorial"},
      limit:{fr:"12 milles",en:"12 miles",es:"12 millas",pt:"12 milhas"},
      rights:{fr:"SOUVERAINETÉ + PASSAGE INNOCENT\n→ Navires étrangers : droit de passage innocent\n→ Passage continu, rapide, non préjudiciable\n→ Sous-marins : navigation en surface obligatoire\n→ État côtier peut établir couloirs\n→ Peut poursuivre violations (COLREG · MARPOL)\n→ Douanes · immigration · santé : compétence côtière",en:"SOVEREIGNTY + INNOCENT PASSAGE\n→ Foreign vessels: right of innocent passage\n→ Continuous, expeditious, non-prejudicial\n→ Submarines: surface navigation mandatory\n→ Coastal state can establish lanes\n→ Can prosecute violations (COLREG · MARPOL)\n→ Customs · immigration · health: coastal jurisdiction",es:"SOBERANÍA + PASO INOCENTE\n→ Buques extranjeros: derecho de paso inocente\n→ Paso continuo, rápido, no perjudicial\n→ Submarinos: navegación en superficie obligatoria\n→ Estado ribereño puede establecer corredores\n→ Puede enjuiciar infracciones (COLREG · MARPOL)",pt:"SOBERANIA + PASSAGEM INOCENTE\n→ Navios estrangeiros: direito de passagem inocente\n→ Passagem contínua, rápida, não prejudicial\n→ Submarinos: navegação à superfície obrigatória\n→ Estado costeiro pode estabelecer corredores\n→ Pode processar violações (COLREG · MARPOL)"}},
    { id:"contiguous", nm:24, width:12, color:C.yellow, icon:"🔍",
      label:{fr:"Zone contiguë",en:"Contiguous zone",es:"Zona contigua",pt:"Zona contígua"},
      limit:{fr:"24 milles",en:"24 miles",es:"24 millas",pt:"24 milhas"},
      rights:{fr:"CONTRÔLE DOUANIER & SANITAIRE\n→ Pas de souveraineté complète\n→ Droit de contrôle : douanes · fiscalité\n→ Immigration · santé (contrôle)\n→ Peut exercer droit de poursuite\n→ Applicable aux infractions sur le territoire\n→ Ni liberté totale ni souveraineté",en:"CUSTOMS & SANITARY CONTROL\n→ No full sovereignty\n→ Right of control: customs · taxation\n→ Immigration · health (control)\n→ Can exercise right of pursuit\n→ Applicable to violations on territory\n→ Neither full freedom nor sovereignty",es:"CONTROL ADUANERO Y SANITARIO\n→ Sin soberanía completa\n→ Derecho de control: aduanas · fiscalidad\n→ Inmigración · salud (control)\n→ Puede ejercer derecho de persecución\n→ Aplicable a infracciones en el territorio",pt:"CONTROLO ADUANEIRO E SANITÁRIO\n→ Sem soberania completa\n→ Direito de controlo: alfândega · fiscalidade\n→ Imigração · saúde (controlo)\n→ Pode exercer direito de perseguição\n→ Aplicável a violações no território"}},
    { id:"eez", nm:200, width:20, color:C.blue2, icon:"🌊",
      label:{fr:"ZEE (Zone Économique Exclusive)",en:"EEZ (Exclusive Economic Zone)",es:"ZEE (Zona Económica Exclusiva)",pt:"ZEE (Zona Económica Exclusiva)"},
      limit:{fr:"200 milles",en:"200 miles",es:"200 millas",pt:"200 milhas"},
      rights:{fr:"DROITS ÉCONOMIQUES SOUVERAINS\n→ Ressources vivantes (pêche exclusive)\n→ Ressources non-vivantes (pétrole, gaz, minéraux)\n→ Énergie (éolien offshore, marémotrice)\n→ Recherche scientifique marine (autorisation)\n→ Liberté de navigation pour les navires étrangers\n→ Liberté de survol\n→ Pose de câbles et pipelines\n→ Concept créé par UNCLOS 1982 (nouveau en droit)",en:"SOVEREIGN ECONOMIC RIGHTS\n→ Living resources (exclusive fishing)\n→ Non-living resources (oil, gas, minerals)\n→ Energy (offshore wind, tidal)\n→ Marine scientific research (authorization)\n→ Freedom of navigation for foreign vessels\n→ Freedom of overflight\n→ Laying cables and pipelines\n→ Concept created by UNCLOS 1982 (new in law)",es:"DERECHOS ECONÓMICOS SOBERANOS\n→ Recursos vivos (pesca exclusiva)\n→ Recursos no vivos (petróleo, gas, minerales)\n→ Energía (eólica marina, maremotriz)\n→ Investigación científica marina (autorización)\n→ Libertad de navegación para buques extranjeros\n→ Libertad de sobrevuelo\n→ Tendido de cables y tuberías",pt:"DIREITOS ECONÓMICOS SOBERANOS\n→ Recursos vivos (pesca exclusiva)\n→ Recursos não-vivos (petróleo, gás, minerais)\n→ Energia (eólica offshore, maremotriz)\n→ Investigação científica marinha (autorização)\n→ Liberdade de navegação para navios estrangeiros\n→ Liberdade de sobrevoo\n→ Colocação de cabos e oleodutos"}},
    { id:"continental", nm:350, width:14, color:C.teal, icon:"⛏️",
      label:{fr:"Plateau continental",en:"Continental shelf",es:"Plataforma continental",pt:"Plataforma continental"},
      limit:{fr:"350 milles max",en:"350 miles max",es:"350 millas máx",pt:"350 milhas máx"},
      rights:{fr:"DROITS SUR LE FOND MARIN\n→ Indépendant de la ZEE\n→ Ressources du sol et sous-sol\n→ Hydrocarbures · minéraux · sable\n→ Peut s'étendre jusqu'à 350 milles\n→ Commission des limites (CLCS) → validation\n→ Pas de droit sur la colonne d'eau au-delà de 200 milles\n→ Nombreuses revendications en cours (Arctique · Atlantique)",en:"RIGHTS OVER THE SEABED\n→ Independent from EEZ\n→ Resources of the seabed and subsoil\n→ Hydrocarbons · minerals · sand\n→ Can extend up to 350 miles\n→ Commission on Limits (CLCS) → validation\n→ No rights over water column beyond 200 miles\n→ Numerous ongoing claims (Arctic · Atlantic)",es:"DERECHOS SOBRE EL FONDO MARINO\n→ Independiente de la ZEE\n→ Recursos del lecho y subsuelo\n→ Hidrocarburos · minerales · arena\n→ Puede extenderse hasta 350 millas\n→ Comisión de Límites (CLPC) → validación\n→ Sin derechos sobre la columna de agua más allá de 200 millas",pt:"DIREITOS SOBRE O FUNDO MARINHO\n→ Independente da ZEE\n→ Recursos do leito e subsolo\n→ Hidrocarbonetos · minerais · areia\n→ Pode estender-se até 350 milhas\n→ Comissão de Limites (CLPC) → validação\n→ Sem direitos sobre a coluna de água além das 200 milhas"}},
    { id:"high", nm:999, width:30, color:C.green, icon:"🌍",
      label:{fr:"Haute mer",en:"High seas",es:"Alta mar",pt:"Alto mar"},
      limit:{fr:"Au-delà de 200 milles",en:"Beyond 200 miles",es:"Más allá de 200 millas",pt:"Além de 200 milhas"},
      rights:{fr:"LIBERTÉ TOTALE (6 LIBERTÉS)\n1. Navigation\n2. Survol\n3. Pose de câbles et pipelines\n4. Construction d'îles artificielles\n5. Pêche (selon conventions)\n6. Recherche scientifique\n\nSEUL L'ÉTAT DU PAVILLON EST COMPÉTENT\nSauf : piraterie · esclavage · trafic de drogue\n→ Compétence universelle limitée\n\nZONE :\nFonds marins au-delà du plateau = 'patrimoine commun de l'humanité'",en:"TOTAL FREEDOM (6 FREEDOMS)\n1. Navigation\n2. Overflight\n3. Laying cables and pipelines\n4. Construction of artificial islands\n5. Fishing (under conventions)\n6. Scientific research\n\nONLY FLAG STATE IS COMPETENT\nExcept: piracy · slavery · drug trafficking\n→ Limited universal jurisdiction\n\nTHE AREA:\nSeabed beyond shelf = 'common heritage of mankind'",es:"LIBERTAD TOTAL (6 LIBERTADES)\n1. Navegación\n2. Sobrevuelo\n3. Tendido de cables y tuberías\n4. Construcción de islas artificiales\n5. Pesca (según convenios)\n6. Investigación científica\n\nSOLO EL ESTADO DE PABELLÓN ES COMPETENTE\nSalvo: piratería · esclavitud · tráfico de drogas",pt:"LIBERDADE TOTAL (6 LIBERDADES)\n1. Navegação\n2. Sobrevoo\n3. Colocação de cabos e oleodutos\n4. Construção de ilhas artificiais\n5. Pesca (segundo convenções)\n6. Investigação científica\n\nAPENAS O ESTADO DE BANDEIRA É COMPETENTE\nExceto: pirataria · escravatura · tráfico de droga"},},
  ];
  const sel_ = sel!==null ? zones[sel] : null;
  const total = zones.reduce((a,z)=>a+z.width,0);
  return (
    <div>
      {/* Zone bar */}
      <div style={{display:"flex",height:18,borderRadius:8,overflow:"hidden",marginBottom:10,gap:1}}>
        {zones.map((z,i)=>(
          <div key={i} onClick={()=>setSel(sel===i?null:i)}
            style={{flex:z.width,background:sel===i?z.color:`${z.color}77`,cursor:"pointer",
              display:"flex",alignItems:"center",justifyContent:"center",transition:"all 0.2s",
              borderRadius:i===0?"8px 0 0 8px":i===zones.length-1?"0 8px 8px 0":"0"}}>
            <span style={{fontSize:6,color:C.white,fontWeight:700,opacity:sel===i?1:0.7}}>
              {z.limit[lang]||z.limit.fr}
            </span>
          </div>
        ))}
      </div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:6,marginBottom:10}}>
        {zones.map((z,i)=>(
          <button key={i} onClick={()=>setSel(sel===i?null:i)} style={{
            padding:"8px 4px",borderRadius:10,cursor:"pointer",textAlign:"center",
            background:sel===i?`${z.color}22`:"rgba(255,255,255,0.04)",
            border:`1.5px solid ${sel===i?z.color:"rgba(255,255,255,0.08)"}`,
          }}>
            <div style={{fontSize:16}}>{z.icon}</div>
            <div style={{fontSize:7,color:sel===i?z.color:C.muted,fontWeight:700,lineHeight:1.2,marginTop:2}}>{z.label[lang]||z.label.fr}</div>
            <div style={{fontSize:6,color:z.color,marginTop:1}}>{z.limit[lang]||z.limit.fr}</div>
          </button>
        ))}
      </div>
      {sel_?<div style={{padding:"12px",borderRadius:14,background:`${sel_.color}12`,border:`1.5px solid ${sel_.color}44`,animation:"fadeUp 0.3s ease"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}>
          <div style={{fontSize:13,fontWeight:700,color:sel_.color}}>{sel_.icon} {sel_.label[lang]||sel_.label.fr}</div>
          <span style={{padding:"2px 8px",borderRadius:8,background:`${sel_.color}22`,fontSize:9,color:sel_.color,fontWeight:700}}>{sel_.limit[lang]||sel_.limit.fr}</span>
        </div>
        <div style={{fontSize:11,color:C.white,lineHeight:1.6,whiteSpace:"pre-line"}}>{sel_.rights[lang]||sel_.rights.fr}</div>
      </div>:<div style={{textAlign:"center",padding:"10px",fontSize:11,color:C.muted}}>
        {lang==="fr"?"Touche une zone pour ses droits":lang==="en"?"Tap a zone for its rights":lang==="es"?"Toca una zona para sus derechos":"Toque numa zona para os seus direitos"}
      </div>}
    </div>
  );
}

