// SVG 3 — RIGHTS SIMULATOR BY ZONE
// ══════════════════════════════════════
function RightsSimulatorSVG({ lang }) {
  const [activity, setActivity] = useState(null);
  const activities = [
    { id:"nav", icon:"🚢", color:C.blue2,
      label:{fr:"Navigation commerciale",en:"Commercial navigation",es:"Navegación comercial",pt:"Navegação comercial"},
      rights:{fr:"Eaux intérieures → Autorisation requise (escale)\nMer territoriale → Passage innocent (libre si continu)\nZone contiguë → Libre passage\nZEE → Liberté totale de navigation\nHaute mer → Liberté totale\n\nRègle : COLREG applicable partout",en:"Internal waters → Authorization required (port call)\nTerritorial sea → Innocent passage (free if continuous)\nContiguous zone → Free passage\nEEZ → Total freedom of navigation\nHigh seas → Total freedom\n\nRule: COLREG applicable everywhere",es:"Aguas interiores → Autorización requerida (escala)\nMar territorial → Paso inocente (libre si continuo)\nZona contigua → Libre paso\nZEE → Libertad total de navegación\nAlta mar → Libertad total\n\nRegla: COLREG aplicable en todas partes",pt:"Águas interiores → Autorização necessária (escala)\nMar territorial → Passagem inocente (livre se contínua)\nZona contígua → Livre passagem\nZEE → Liberdade total de navegação\nAlto mar → Liberdade total\n\nRegra: COLREG aplicável em todo o lado"}},
    { id:"fish", icon:"🎣", color:C.orange,
      label:{fr:"Pêche commerciale",en:"Commercial fishing",es:"Pesca comercial",pt:"Pesca comercial"},
      rights:{fr:"Eaux intérieures → INTERDIT (sans autorisation)\nMer territoriale → INTERDIT (sans accord bilatéral)\nZone contiguë → INTERDIT\nZEE → INTERDIT pour navires étrangers\n(État côtier = droits exclusifs de pêche)\nHaute mer → LIBRE (selon conventions ICCAT etc.)\n\nViolation ZEE = arraisonnement possible\nAmende + saisie du navire et de la cargaison",en:"Internal waters → PROHIBITED (without authorization)\nTerritorial sea → PROHIBITED (without bilateral agreement)\nContiguous zone → PROHIBITED\nEEZ → PROHIBITED for foreign vessels\n(Coastal state = exclusive fishing rights)\nHigh seas → FREE (under ICCAT etc. conventions)\n\nEEZ violation = possible boarding\nFine + seizure of vessel and cargo",es:"Aguas interiores → PROHIBIDO (sin autorización)\nMar territorial → PROHIBIDO (sin acuerdo bilateral)\nZona contigua → PROHIBIDO\nZEE → PROHIBIDO para buques extranjeros\n(Estado ribereño = derechos exclusivos de pesca)\nAlta mar → LIBRE (según convenios ICCAT etc.)\n\nInfracción ZEE = posible abordaje\nMulta + incautación del buque y la carga",pt:"Águas interiores → PROIBIDO (sem autorização)\nMar territorial → PROIBIDO (sem acordo bilateral)\nZona contígua → PROIBIDO\nZEE → PROIBIDO para navios estrangeiros\n(Estado costeiro = direitos exclusivos de pesca)\nAlto mar → LIVRE (segundo convenções ICCAT etc.)\n\nViolação ZEE = possível abordagem\nMulta + apreensão do navio e carga"}},
    { id:"research", icon:"🔬", color:C.purple,
      label:{fr:"Recherche scientifique",en:"Scientific research",es:"Investigación científica",pt:"Investigação científica"},
      rights:{fr:"Eaux intérieures → Autorisation obligatoire\nMer territoriale → Autorisation obligatoire\nZEE → AUTORISATION de l'État côtier obligatoire\n(Article 246 UNCLOS)\nPlateau continental → Autorisation obligatoire\nHaute mer → LIBRE (Article 87 + 238-265)\n\nRefus d'autorisation ZEE = droit de l'État côtier\nRecherche à des fins militaires = pas protégée",en:"Internal waters → Authorization mandatory\nTerritorial sea → Authorization mandatory\nEEZ → Coastal state AUTHORIZATION mandatory\n(UNCLOS Article 246)\nContinental shelf → Authorization mandatory\nHigh seas → FREE (Articles 87 + 238-265)\n\nRefusal of EEZ authorization = coastal state right\nMilitary research = not protected",es:"Aguas interiores → Autorización obligatoria\nMar territorial → Autorización obligatoria\nZEE → Autorización obligatoria del Estado ribereño\n(Artículo 246 CONVEMAR)\nPlataforma continental → Autorización obligatoria\nAlta mar → LIBRE (Artículos 87 + 238-265)\n\nDenegación autorización ZEE = derecho del Estado ribereño",pt:"Águas interiores → Autorização obrigatória\nMar territorial → Autorização obrigatória\nZEE → Autorização do Estado costeiro obrigatória\n(Artigo 246 UNCLOS)\nPlataforma continental → Autorização obrigatória\nAlto mar → LIVRE (Artigos 87 + 238-265)\n\nRecusa autorização ZEE = direito do Estado costeiro"}},
    { id:"pipeline", icon:"🔧", color:C.teal,
      label:{fr:"Pose de câbles/pipelines",en:"Cable/pipeline laying",es:"Tendido de cables/tuberías",pt:"Colocação de cabos/oleodutos"},
      rights:{fr:"Eaux intérieures → Autorisation obligatoire\nMer territoriale → Autorisation obligatoire\nZEE → LIBRE (mais notification État côtier)\nPlateau continental → Consentement État côtier requis\n(tracé du pipeline)\nHaute mer → LIBERTÉ TOTALE (Art.87 + 112-115)\n\nImportance : câbles sous-marins = 97% internet mondial\nProtection : dommager un câble = infraction internationale",en:"Internal waters → Authorization mandatory\nTerritorial sea → Authorization mandatory\nEEZ → FREE (but coastal state notification)\nContinental shelf → Coastal state consent required\n(pipeline route)\nHigh seas → TOTAL FREEDOM (Art.87 + 112-115)\n\nImportance: submarine cables = 97% of world internet\nProtection: damaging a cable = international violation",es:"Aguas interiores → Autorización obligatoria\nMar territorial → Autorización obligatoria\nZEE → LIBRE (pero notificación al Estado ribereño)\nPlataforma continental → Consentimiento Estado ribereño requerido\n(trazado del oleoducto)\nAlta mar → LIBERTAD TOTAL (Art.87 + 112-115)\n\nImportancia: cables submarinos = 97% internet mundial",pt:"Águas interiores → Autorização obrigatória\nMar territorial → Autorização obrigatória\nZEE → LIVRE (mas notificação ao Estado costeiro)\nPlataforma continental → Consentimento do Estado costeiro necessário\n(traçado do oleoduto)\nAlto mar → LIBERDADE TOTAL (Art.87 + 112-115)\n\nImportância: cabos submarinos = 97% da internet mundial"},},
  ];
  const act = activity!==null ? activities[activity] : null;
  return (
    <div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:10}}>
        {activities.map((a,i)=>(
          <button key={i} onClick={()=>setActivity(activity===i?null:i)} style={{
            padding:"10px 6px",borderRadius:12,cursor:"pointer",textAlign:"center",
            background:activity===i?`${a.color}22`:"rgba(255,255,255,0.04)",
            border:`1.5px solid ${activity===i?a.color:"rgba(255,255,255,0.08)"}`,
          }}>
            <div style={{fontSize:22,marginBottom:4}}>{a.icon}</div>
            <div style={{fontSize:9,color:activity===i?a.color:C.muted,fontWeight:700,lineHeight:1.3}}>{a.label[lang]||a.label.fr}</div>
          </button>
        ))}
      </div>
      {act?<div style={{padding:"12px",borderRadius:14,background:`${act.color}12`,border:`1.5px solid ${act.color}44`,animation:"fadeUp 0.3s ease"}}>
        <div style={{fontSize:13,fontWeight:700,color:act.color,marginBottom:8}}>{act.icon} {act.label[lang]||act.label.fr}</div>
        <div style={{fontSize:11,color:C.white,lineHeight:1.7,whiteSpace:"pre-line"}}>{act.rights[lang]||act.rights.fr}</div>
      </div>:<div style={{textAlign:"center",padding:"10px",fontSize:11,color:C.muted}}>
        {lang==="fr"?"Choisis une activité pour voir les droits par zone":lang==="en"?"Choose an activity to see rights by zone":lang==="es"?"Elige una actividad para ver los derechos por zona":"Escolha uma atividade para ver os direitos por zona"}
      </div>}
    </div>
  );
}

// ══════════════════════════════════════
// SVG 4 — DISPUTE RESOLUTION
// ══════════════════════════════════════
function DisputeResolutionSVG({ lang }) {
  const [sel, setSel] = useState(null);
  const mechanisms = [
    { id:"tidm", icon:"⚖️", color:C.blue2,
      label:{fr:"TIDM — Tribunal International\ndu Droit de la Mer",en:"ITLOS — International Tribunal\nfor the Law of the Sea",es:"TIDM — Tribunal Internacional\ndel Derecho del Mar",pt:"TIDM — Tribunal Internacional\ndo Direito do Mar"},
      desc:{fr:"Siège : Hambourg, Allemagne\nCréé par UNCLOS Annexe VI (1982)\nEn fonction depuis 1996\n21 juges élus par les États parties\nMandat : 9 ans · non-renouvelable\nCompétences :\n→ Différends entre États sur UNCLOS\n→ Libération rapide de navires arraisonnés\n→ Mesures conservatoires d'urgence\n→ Opinions consultatives\nExemple : MV Saiga (1997) — Saint-Vincent vs Guinée",en:"Seat: Hamburg, Germany\nCreated by UNCLOS Annex VI (1982)\nOperational since 1996\n21 judges elected by states parties\nMandate: 9 years · non-renewable\nJurisdiction:\n→ Disputes between states on UNCLOS\n→ Prompt release of arrested vessels\n→ Provisional measures (urgent)\n→ Advisory opinions\nExample: MV Saiga (1997) — St Vincent vs Guinea",es:"Sede: Hamburgo, Alemania\nCreado por CONVEMAR Anexo VI (1982)\nEn funcionamiento desde 1996\n21 jueces elegidos por los Estados parte\nMandato: 9 años · no renovable\nCompetencias:\n→ Controversias entre Estados sobre CONVEMAR\n→ Pronta liberación de buques detenidos\n→ Medidas cautelares de urgencia\n→ Dictámenes consultivos",pt:"Sede: Hamburgo, Alemanha\nCriado pela UNCLOS Anexo VI (1982)\nEm funcionamento desde 1996\n21 juízes eleitos pelos estados partes\nMandato: 9 anos · não renovável\nCompetências:\n→ Controvérsias entre estados sobre UNCLOS\n→ Libertação rápida de navios detidos\n→ Medidas provisórias de urgência\n→ Pareceres consultivos"}},
    { id:"cij", icon:"🌍", color:C.gold2,
      label:{fr:"CIJ — Cour Internationale\nde Justice",en:"ICJ — International\nCourt of Justice",es:"CIJ — Corte Internacional\nde Justicia",pt:"TIJ — Tribunal Internacional\nde Justiça"},
      desc:{fr:"Siège : La Haye, Pays-Bas\nOrgane judiciaire principal de l'ONU\nCompétence UNCLOS :\n→ Si les deux États y consentent\n→ Alternative au TIDM\n→ Délais plus longs que TIDM\nExemple célèbre :\nNicaragua vs Colombie (2012) — délimitation maritime\nDélimitation maritime : compétence CIJ + TIDM\nUsage souvent pour conflits de souveraineté",en:"Seat: The Hague, Netherlands\nPrincipal judicial organ of the UN\nUNCLOS jurisdiction:\n→ If both states consent\n→ Alternative to ITLOS\n→ Longer timelines than ITLOS\nFamous example:\nNicaragua v. Colombia (2012) — maritime delimitation\nMaritime delimitation: ICJ + ITLOS jurisdiction\nOften used for sovereignty conflicts",es:"Sede: La Haya, Países Bajos\nÓrgano judicial principal de la ONU\nCompetencia CONVEMAR:\n→ Si ambos Estados consienten\n→ Alternativa al TIDM\n→ Plazos más largos que el TIDM\nEjemplo famoso:\nNicaragua vs Colombia (2012) — delimitación marítima",pt:"Sede: Haia, Países Baixos\nÓrgão judicial principal da ONU\nCompetência UNCLOS:\n→ Se ambos os estados consentirem\n→ Alternativa ao TIDM\n→ Prazos mais longos que o TIDM\nExemplo famoso:\nNicaragua vs Colômbia (2012) — delimitação marítima"}},
    { id:"arbitrage7", icon:"📋", color:C.green,
      label:{fr:"Arbitrage Annexe VII",en:"Annex VII Arbitration",es:"Arbitraje Anexo VII",pt:"Arbitragem Anexo VII"},
      desc:{fr:"MÉCANISME PAR DÉFAUT UNCLOS\nSi les parties ne s'accordent sur aucun autre mécanisme\n→ Arbitrage Annexe VII s'applique automatiquement\nTribunal ad hoc : 5 arbitres\nCas célèbre : Philippines vs Chine (2016)\n\nAVANTAGES :\n→ Obligatoire même si une partie refuse\n→ Sentence finale et obligatoire\n→ Pas de veto possible\nLIMITES :\n→ Aucun mécanisme d'exécution forcée\n→ Chine a ignoré la sentence de 2016",en:"UNCLOS DEFAULT MECHANISM\nIf parties don't agree on any other mechanism\n→ Annex VII Arbitration applies automatically\nAd hoc tribunal: 5 arbitrators\nFamous case: Philippines v. China (2016)\n\nADVANTAGES:\n→ Mandatory even if one party refuses\n→ Final and binding award\n→ No veto possible\nLIMITATIONS:\n→ No forced execution mechanism\n→ China ignored 2016 award",es:"MECANISMO POR DEFECTO CONVEMAR\nSi las partes no se ponen de acuerdo en otro mecanismo\n→ El arbitraje del Anexo VII se aplica automáticamente\nTribunal ad hoc: 5 árbitros\nCaso famoso: Filipinas vs China (2016)\n\nVENTAJAS:\n→ Obligatorio aunque una parte se niegue\n→ Laudo definitivo y vinculante\n→ Sin veto posible\nLIMITACIONES:\n→ Sin mecanismo de ejecución forzosa\n→ China ignoró el laudo de 2016",pt:"MECANISMO POR DEFEITO UNCLOS\nSe as partes não acordarem noutro mecanismo\n→ Arbitragem Anexo VII aplica-se automaticamente\nTribunal ad hoc: 5 árbitros\nCaso famoso: Filipinas vs China (2016)\n\nVANTAGENS:\n→ Obrigatório mesmo que uma parte recuse\n→ Sentença final e vinculativa\n→ Sem veto possível\nLIMITAÇÕES:\n→ Sem mecanismo de execução forçada\n→ China ignorou a sentença de 2016"},},
    { id:"conciliation", icon:"🤝", color:C.orange,
      label:{fr:"Conciliation\n& négociation",en:"Conciliation\n& negotiation",es:"Conciliación\ny negociación",pt:"Conciliação\ne negociação"},
      desc:{fr:"MÉTHODES NON-CONTENTIEUSES\n\n1. Négociation directe entre États\n→ La plus courante · rapide · discrète\n→ Accord bilatéral possible\n\n2. Conciliation (Annexe V UNCLOS)\n→ Commission de conciliation\n→ Non-contraignant (recommandation)\n→ Timor-Leste vs Australie (2016-2018)\n\n3. Médiation\n→ Tiers facilitateur\n→ Non-contraignant\n\nPréférence des grandes puissances :\nChine · USA · Russie = préfèrent négociation bilatérale\nRefusent souvent les mécanismes contraignants",en:"NON-CONTENTIOUS METHODS\n\n1. Direct negotiation between states\n→ Most common · quick · discreet\n→ Bilateral agreement possible\n\n2. Conciliation (UNCLOS Annex V)\n→ Conciliation commission\n→ Non-binding (recommendation)\n→ Timor-Leste v. Australia (2016-2018)\n\n3. Mediation\n→ Third-party facilitator\n→ Non-binding\n\nGreat power preference:\nChina · USA · Russia = prefer bilateral negotiation\nOften refuse binding mechanisms",es:"MÉTODOS NO CONTENCIOSOS\n\n1. Negociación directa entre Estados\n→ La más habitual · rápida · discreta\n→ Acuerdo bilateral posible\n\n2. Conciliación (Anexo V CONVEMAR)\n→ Comisión de conciliación\n→ No vinculante (recomendación)\n→ Timor-Leste vs Australia (2016-2018)\n\n3. Mediación\n→ Tercero facilitador\n→ No vinculante",pt:"MÉTODOS NÃO CONTENCIOSOS\n\n1. Negociação direta entre estados\n→ Mais comum · rápida · discreta\n→ Acordo bilateral possível\n\n2. Conciliação (Anexo V UNCLOS)\n→ Comissão de conciliação\n→ Não vinculativa (recomendação)\n→ Timor-Leste vs Austrália (2016-2018)\n\n3. Mediação\n→ Terceiro facilitador\n→ Não vinculativa"},},
  ];
  const sel_ = sel!==null ? mechanisms[sel] : null;
  return (
    <div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:10}}>
        {mechanisms.map((m,i)=>(
          <div key={i} onClick={()=>setSel(sel===i?null:i)}
            style={{padding:"10px 6px",borderRadius:12,cursor:"pointer",textAlign:"center",
              background:sel===i?`${m.color}22`:"rgba(255,255,255,0.04)",
              border:`1.5px solid ${sel===i?m.color:"rgba(255,255,255,0.08)"}`}}>
            <div style={{fontSize:22,marginBottom:4}}>{m.icon}</div>
            <div style={{fontSize:8,color:sel===i?m.color:C.muted,fontWeight:700,lineHeight:1.3,whiteSpace:"pre-line"}}>{m.label[lang]||m.label.fr}</div>
          </div>
        ))}
      </div>
      {sel_?<div style={{padding:"12px",borderRadius:14,background:`${sel_.color}12`,border:`1.5px solid ${sel_.color}44`,animation:"fadeUp 0.3s ease"}}>
        <div style={{fontSize:13,fontWeight:700,color:sel_.color,marginBottom:6}}>{sel_.icon} {(sel_.label[lang]||sel_.label.fr).replace('\n',' ')}</div>
        <div style={{fontSize:11,color:C.white,lineHeight:1.6,whiteSpace:"pre-line"}}>{sel_.desc[lang]||sel_.desc.fr}</div>
      </div>:<div style={{textAlign:"center",padding:"10px",fontSize:11,color:C.muted}}>
        {lang==="fr"?"Touche un mécanisme pour les détails":lang==="en"?"Tap a mechanism for details":lang==="es"?"Toca un mecanismo para detalles":"Toque num mecanismo para detalhes"}
      </div>}
    </div>
  );
}

// ══════════════════════════════════════
// ACCIDENT CASE
// ══════════════════════════════════════
function AccidentCase({ lang }) {
  const [exp,setExp]=useState(false);
  const d={
    fr:{title:"Affaire Philippines vs Chine — Mer de Chine du Sud (2016)",teaser:"Arbitrage UNCLOS · Ligne des 9 tirets · Sentence ignorée · Limites du droit international",what:"Les Philippines saisissent le Tribunal Arbitral (Annexe VII UNCLOS) contre les revendications chinoises en Mer de Chine du Sud, représentées par la 'Ligne des 9 tirets' couvrant environ 90% de la mer. La Chine prétend avoir des 'droits historiques' sur ces eaux. Elle refuse de participer à la procédure arbitrale.",cause:"• Chine : 'droits historiques' sans base légale UNCLOS\n• Construction d'îles artificielles sur récifs philippins (ZEE)\n• Obstruction des pêcheurs philippins dans leur propre ZEE\n• Refus de reconnaître la compétence du tribunal\n• La Chine n'a pas ratifié la partie XI d'UNCLOS",lessons:"✓ Sentence du 12 juillet 2016 : Ligne des 9 tirets = sans base légale UNCLOS\n✓ Chine a violé les droits de la ZEE des Philippines\n✓ Construction d'îles artificielles = illégale\n✓ MAIS : Chine refuse d'appliquer la sentence\n✓ Démontre : UNCLOS = outil puissant mais sans exécution forcée\n✓ Leçon : les grandes puissances peuvent ignorer les sentences internationales",link:"🔗 Lien L6 UNCLOS : Cette affaire est le test ultime d'UNCLOS. La convention est juridiquement solide mais politiquement limitée. Elle prouve que le droit international ne vaut que si les États acceptent de s'y soumettre."},
    en:{title:"Philippines vs China — South China Sea (2016)",teaser:"UNCLOS Arbitration · 9-dash line · Award ignored · Limits of international law",what:"Philippines invokes the Arbitral Tribunal (UNCLOS Annex VII) against Chinese claims in the South China Sea, represented by the '9-dash line' covering approximately 90% of the sea. China claims 'historic rights' over these waters. It refuses to participate in the arbitral proceedings.",cause:"• China: 'historic rights' without UNCLOS legal basis\n• Construction of artificial islands on Philippine reefs (EEZ)\n• Obstruction of Philippine fishermen in their own EEZ\n• Refusal to recognize tribunal jurisdiction\n• China did not ratify Part XI of UNCLOS",lessons:"✓ Award of July 12, 2016: 9-dash line = no legal basis in UNCLOS\n✓ China violated Philippines' EEZ rights\n✓ Artificial island construction = illegal\n✓ BUT: China refuses to implement the award\n✓ Shows: UNCLOS = powerful tool but without forced enforcement\n✓ Lesson: major powers can ignore international awards",link:"🔗 L6 UNCLOS Link: This case is the ultimate test of UNCLOS. The convention is legally sound but politically limited. It proves international law is only worth what states agree to submit to."},
    es:{title:"Filipinas vs China — Mar de China Meridional (2016)",teaser:"Arbitraje CONVEMAR · Línea de los 9 puntos · Laudo ignorado · Límites del derecho internacional",what:"Filipinas presenta una demanda ante el Tribunal Arbitral (Anexo VII CONVEMAR) contra las reclamaciones chinas en el Mar de China Meridional, representadas por la 'Línea de los 9 puntos' que abarca aproximadamente el 90% del mar. China alega tener 'derechos históricos' sobre estas aguas.",cause:"• China: 'derechos históricos' sin base legal CONVEMAR\n• Construcción de islas artificiales en arrecifes filipinos (ZEE)\n• Obstaculización de pescadores filipinos en su propia ZEE\n• Negativa a reconocer la competencia del tribunal",lessons:"✓ Laudo del 12 julio 2016: Línea de los 9 puntos = sin base legal CONVEMAR\n✓ China violó los derechos de la ZEE de Filipinas\n✓ Construcción de islas artificiales = ilegal\n✓ PERO: China se niega a aplicar el laudo\n✓ Demuestra: CONVEMAR = herramienta poderosa pero sin ejecución forzosa",link:"🔗 Vínculo L6: Esta controversia es la prueba definitiva de CONVEMAR. El convenio es jurídicamente sólido pero políticamente limitado."},
    pt:{title:"Filipinas vs China — Mar do Sul da China (2016)",teaser:"Arbitragem UNCLOS · Linha dos 9 traços · Sentença ignorada · Limites do direito internacional",what:"As Filipinas recorrem ao Tribunal Arbitral (Anexo VII UNCLOS) contra as reivindicações chinesas no Mar do Sul da China, representadas pela 'Linha dos 9 traços' cobrindo aproximadamente 90% do mar. A China alega ter 'direitos históricos' sobre estas águas.",cause:"• China: 'direitos históricos' sem base legal UNCLOS\n• Construção de ilhas artificiais em recifes filipinos (ZEE)\n• Obstaculização de pescadores filipinos na sua própria ZEE\n• Recusa de reconhecer a competência do tribunal",lessons:"✓ Sentença de 12 julho 2016: Linha dos 9 traços = sem base legal UNCLOS\n✓ China violou os direitos da ZEE das Filipinas\n✓ Construção de ilhas artificiais = ilegal\n✓ MAS: China recusa implementar a sentença\n✓ Demonstra: UNCLOS = ferramenta poderosa mas sem execução forçada",link:"🔗 Vínculo L6: Este caso é o teste definitivo da UNCLOS. A convenção é juridicamente sólida mas politicamente limitada."},
  };
  const c=d[lang]||d.fr;
  return(
    <div style={{background:"rgba(26,111,212,0.08)",border:`1.5px solid ${C.blue2}44`,borderRadius:18,overflow:"hidden"}}>
      <div style={{padding:"14px 16px",cursor:"pointer"}} onClick={()=>setExp(v=>!v)}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{fontSize:22}}>⚖️</span>
          <div style={{flex:1}}><div style={{fontSize:13,fontWeight:700,color:C.blue2,marginBottom:2}}>{c.title}</div><div style={{fontSize:11,color:C.muted,lineHeight:1.4}}>{c.teaser}</div></div>
          <span style={{fontSize:14,color:C.muted}}>{exp?"▲":"▼"}</span>
        </div>
      </div>
      {exp&&<div style={{padding:"0 16px 16px"}}>
        <div style={{fontSize:12,color:C.white,lineHeight:1.7,marginBottom:10}}>{c.what}</div>
        <div style={{fontSize:11,color:C.red,fontWeight:700,marginBottom:5,fontFamily:"'Cinzel',serif"}}>CAUSES</div>
        <div style={{fontSize:12,color:C.white,lineHeight:1.7,whiteSpace:"pre-line",marginBottom:10}}>{c.cause}</div>
        <div style={{fontSize:11,color:C.green,fontWeight:700,marginBottom:5,fontFamily:"'Cinzel',serif"}}>{lang==="fr"?"LEÇONS":lang==="en"?"LESSONS":lang==="es"?"LECCIONES":"LIÇÕES"}</div>
        <div style={{fontSize:12,color:C.white,lineHeight:1.7,whiteSpace:"pre-line",marginBottom:10}}>{c.lessons}</div>
        <div style={{padding:"10px 12px",borderRadius:10,background:"rgba(201,146,42,0.1)",border:`1px solid ${C.gold}33`,fontSize:11,color:C.gold2,lineHeight:1.6}}>{c.link}</div>
      </div>}
    </div>
  );
}

// ══════════════════════════════════════
// EXERCISE
// ══════════════════════════════════════
function Exercise1({ lang, t }) {
  const [ans,setAns]=useState({q1:"",q2:"",q3:""});
  const [showC,setShowC]=useState(false);
  const qs={
    fr:[
      {id:"q1",q:"Où a été adoptée la Convention UNCLOS et en quelle année ?\n(Répondre : ville + année)",correct:"Montego Bay 1982"},
      {id:"q2",q:"Quelle est la limite en milles nautiques de la ZEE ?\n(Répondre : le chiffre)",correct:"200"},
      {id:"q3",q:"TIDM = ? (Nom complet en français)\n(Répondre : Tribunal...)",correct:"Tribunal International du Droit de la Mer"},
    ],
    en:[
      {id:"q1",q:"Where and when was the UNCLOS Convention adopted?\n(Answer: city + year)",correct:"Montego Bay 1982"},
      {id:"q2",q:"What is the nautical mile limit of the EEZ?\n(Answer: the number)",correct:"200"},
      {id:"q3",q:"ITLOS = ? (Full name)\n(Answer: International...)",correct:"International Tribunal for the Law of the Sea"},
    ],
    es:[
      {id:"q1",q:"¿Dónde y en qué año fue adoptada la CONVEMAR?\n(Responder: ciudad + año)",correct:"Montego Bay 1982"},
      {id:"q2",q:"¿Cuál es el límite en millas náuticas de la ZEE?\n(Responder: el número)",correct:"200"},
      {id:"q3",q:"TIDM = ? (Nombre completo en español)\n(Responder: Tribunal...)",correct:"Tribunal Internacional del Derecho del Mar"},
    ],
    pt:[
      {id:"q1",q:"Onde e em que ano foi adotada a UNCLOS?\n(Responder: cidade + ano)",correct:"Montego Bay 1982"},
      {id:"q2",q:"Qual é o limite em milhas náuticas da ZEE?\n(Responder: o número)",correct:"200"},
      {id:"q3",q:"TIDM = ? (Nome completo)\n(Responder: Tribunal...)",correct:"Tribunal Internacional do Direito do Mar"},
    ],
  };
  const list=qs[lang]||qs.fr;
  const chk=(q,val)=>{
    const v=val.trim().toLowerCase();
    if(q.id==="q1") return v.includes("montego")&&v.includes("1982");
    if(q.id==="q2") return v.includes("200");
    if(q.id==="q3") return v.includes("tribunal")&&(v.includes("mer")||v.includes("sea")||v.includes("mar"));
    return false;
  };
  return(
    <div>
      <div style={{background:"rgba(0,0,0,0.4)",borderRadius:12,padding:"10px 12px",marginBottom:12,border:`1px solid ${C.blue2}44`,fontSize:11,color:C.gold2,lineHeight:1.6}}>
        {lang==="fr"?"💡 Rappels : Montego Bay 1982 · ZEE = 200 milles · TIDM = Tribunal Int. Droit de la Mer (Hambourg)"
        :lang==="en"?"💡 Reminders: Montego Bay 1982 · EEZ = 200 miles · ITLOS = Int. Tribunal Law of the Sea (Hamburg)"
        :lang==="es"?"💡 Recordatorios: Montego Bay 1982 · ZEE = 200 millas · TIDM = Tribunal Int. Derecho del Mar (Hamburgo)"
        :"💡 Lembretes: Montego Bay 1982 · ZEE = 200 milhas · TIDM = Tribunal Int. Direito do Mar (Hamburgo)"}
      </div>
      {list.map((q,i)=>(
        <div key={q.id} style={{marginBottom:12}}>
          <div style={{fontSize:12,color:C.white,marginBottom:6,lineHeight:1.5,whiteSpace:"pre-line",fontWeight:600}}>{i+1}. {q.q}</div>
          <input type="text" value={ans[q.id]} onChange={e=>setAns(a=>({...a,[q.id]:e.target.value}))} placeholder="?"
            style={{width:"100%",padding:"10px",borderRadius:10,background:"rgba(255,255,255,0.07)",border:`1px solid ${showC?(chk(q,ans[q.id])?C.green:C.red):C.border}`,color:C.white,fontSize:14,fontFamily:"monospace",fontWeight:700,textAlign:"center",boxSizing:"border-box"}}/>
          {showC&&<div style={{fontSize:11,marginTop:4,fontWeight:600,color:chk(q,ans[q.id])?C.green:C.red}}>{chk(q,ans[q.id])?"✓":`✗ → ${q.correct}`}</div>}
        </div>
      ))}
      {showC&&<div style={{padding:"12px",borderRadius:12,background:"rgba(30,138,74,0.1)",border:`1px solid ${C.green}44`,fontSize:11,color:C.white,lineHeight:1.7,marginBottom:10}}>
        {lang==="fr"?"✅ Q1: Montego Bay, Jamaïque (10 décembre 1982)\n✅ Q2: 200 milles nautiques (ZEE créée par UNCLOS 1982)\n✅ Q3: Tribunal International du Droit de la Mer · Hambourg · depuis 1996"
        :lang==="en"?"✅ Q1: Montego Bay, Jamaica (December 10, 1982)\n✅ Q2: 200 nautical miles (EEZ created by UNCLOS 1982)\n✅ Q3: International Tribunal for the Law of the Sea · Hamburg · since 1996"
        :"✅ Q1: Montego Bay 1982 · Q2: 200 millas · Q3: Tribunal Internacional del Derecho del Mar"}
      </div>}
      <button onClick={()=>setShowC(v=>!v)} style={{width:"100%",padding:"11px 0",borderRadius:12,background:showC?"rgba(30,138,74,0.2)":"rgba(201,146,42,0.15)",border:`1px solid ${showC?C.green:C.gold}44`,color:showC?C.green:C.gold2,fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:"'Cinzel',serif"}}>
        {showC?t.hideCorr:t.showCorr}
      </button>
    </div>
  );
}

