const BANK = {
  fr:[
    {q:"Qu'est-ce que la 'ligne de base' (baseline) en droit UNCLOS ?",opts:["Le niveau moyen de la mer","Ligne à partir de laquelle se mesurent toutes les zones maritimes — généralement la laisse de basse mer · peut être une ligne de base droite (archipels)","La limite entre ZEE et haute mer","La côte officielle d'un État"],correct:1,expl:"Ligne de base = référence fondamentale pour mesurer toutes les zones maritimes (mer territoriale, zone contiguë, ZEE, plateau continental). Normalement = laisse de basse mer (low-water line). Exception : lignes de base droites (archipels, côtes très découpées — Norvège, Indonésie). Points de base marqués sur les cartes marines. C'est depuis la ligne de base que commence le comptage des 12+24+200 milles."},
    {q:"Qu'est-ce que le 'passage en transit' dans les détroits internationaux ?",opts:["Le passage innocent simplifié","Droit de passage continu et rapide dans les détroits utilisés pour la navigation internationale — sous-marins peuvent passer immergés","Un passage commercial payant","Un droit réservé aux États riverains"],correct:1,expl:"Passage en transit (UNCLOS Art.37-44) = régime spécial pour les détroits internationaux (Malacca, Gibraltar, Hormuz, Bab-el-Mandeb). Différent du passage innocent : les sous-marins peuvent passer IMMERGÉS, les avions militaires peuvent survoler. L'État riverain ne peut pas suspendre le passage en transit. Importance stratégique majeure pour les marines militaires mondiales."},
    {q:"Qu'est-ce que la 'Commission des Limites du Plateau Continental' (CLPC) ?",opts:["Une juridiction maritime","Commission d'experts scientifiques créée par UNCLOS pour valider les revendications d'extension du plateau continental au-delà de 200 milles","Un organisme de l'OMI","Un tribunal arbitral"],correct:1,expl:"CLPC = Commission on the Limits of the Continental Shelf. Organe scientifique créé par UNCLOS Annexe II. Examine les demandes d'extension du plateau continental au-delà de 200 milles (jusqu'à 350 milles max). Les États ont 10 ans après ratification pour soumettre leurs revendications. Exemples : France, Australie, Canada, Russie ont soumis des demandes pour l'Arctique. Ne tranche pas les différends — valide scientifiquement les demandes."},
    {q:"Qu'est-ce que la 'Zone' (Area) dans le droit UNCLOS ?",opts:["La ZEE","Les fonds marins et leur sous-sol au-delà du plateau continental — 'patrimoine commun de l'humanité' géré par l'Autorité internationale des fonds marins","La haute mer","Le plateau continental"],correct:1,expl:"La Zone (Area) = fonds marins et leur sous-sol au-delà des plateaux continentaux. Régime créé par UNCLOS Partie XI. Qualifiée de 'patrimoine commun de l'humanité' = ni les États ni les particuliers ne peuvent en revendiquer la souveraineté. Gérée par l'Autorité internationale des fonds marins (ISA, Kingston). Contient d'immenses ressources minérales (nodules polymétalliques, sulfures hydrothermaux)."},
    {q:"Qu'est-ce que le droit de 'poursuite en haute mer' (hot pursuit) selon UNCLOS ?",opts:["Un droit commercial","Droit d'un État côtier de poursuivre en haute mer un navire étranger ayant violé ses lois dans ses eaux — poursuite immédiate et continue obligatoire","Un droit militaire","Un droit de l'OMI"],correct:1,expl:"Hot pursuit (UNCLOS Art.111) = droit de poursuite en haute mer. Conditions : la poursuite commence DANS les eaux sous juridiction (eaux intérieures, mer territoriale, ZEE), elle est immédiate et continue (pas d'interruption), elle cesse si le navire entre dans les eaux d'un État tiers. Signaux d'arrêt doivent être envoyés. Preuve audio/visuelle requise. Fondement légal des interceptions en haute mer."},
    {q:"Qu'est-ce que l'Autorité Internationale des Fonds Marins (ISA) ?",opts:["Un tribunal maritime","Organisation internationale créée par UNCLOS gérant les ressources de la Zone — délivre les licences d'exploration et d'exploitation minière des fonds marins","Un organe de l'OMI","Un fonds de développement maritime"],correct:1,expl:"ISA = International Seabed Authority (Autorité internationale des fonds marins). Siège : Kingston, Jamaïque. Créée par UNCLOS Partie XI. Rôle : réglementer l'exploration et l'exploitation des ressources minérales des fonds marins au-delà des plateaux continentaux. Délivre des contrats d'exploration à des entreprises (Contractor). Recettes partagées avec les pays en développement. 168 membres."},
    {q:"Qu'est-ce que le 'droit de l'État côtier sur l'épave' en UNCLOS ?",opts:["Un droit commercial de récupération","Selon la zone, l'État côtier peut avoir des droits variables sur les épaves — ZEE : droits limités · eaux territoriales : droits étendus · haute mer : liberté de récupération","L'État côtier n'a aucun droit sur les épaves","Seul l'État du pavillon a des droits"],correct:1,expl:"Épaves et UNCLOS : dépend de la zone. Eaux intérieures/mer territoriale = souveraineté totale de l'État côtier (peut contraindre au renflouement). ZEE = droits sur la pollution mais droits limités sur l'épave. Haute mer = liberté de récupération (sous réserve des droits de l'État du pavillon). Convention de Nairobi (2007) sur le retrait des épaves = complète UNCLOS pour les épaves dangereuses."},
    {q:"Qu'est-ce que le 'droit de visite' (right of visit) en haute mer ?",opts:["Un droit de tourisme","Droit exceptionnel d'un navire de guerre de monter à bord d'un navire étranger suspect en haute mer — limité à des cas précis (piraterie, esclavage, drogue)","Un droit portuaire","Un droit commercial"],correct:1,expl:"Droit de visite (UNCLOS Art.110) = exception au principe d'exclusivité du pavillon. Un navire de guerre peut arraisonner un navire étranger en haute mer UNIQUEMENT si : suspicion de piraterie, suspicion de traite des personnes, suspicion de trafic de stupéfiants, diffusion non autorisée, navire sans nationalité. Si suspicion non confirmée : indemnisation du navire arraisonné. Base légale des opérations anti-piraterie (OTAN, EU Navfor)."},
    {q:"Qu'est-ce que l'UNCLOS dit sur les 'îles artificielles' ?",opts:["Elles créent une ZEE automatiquement","Elles ne génèrent pas de mer territoriale, ZEE ni plateau continental — seulement une zone de sécurité de 500 mètres","Elles ont les mêmes droits qu'une île naturelle","Elles appartiennent à l'OMI"],correct:1,expl:"Îles artificielles (UNCLOS Art.60) : une île artificielle, installation ou structure construite par un État dans sa ZEE ne génère PAS de mer territoriale, ZEE ou plateau continental. Seule une zone de sécurité de 500 mètres maximum peut être établie. C'est pourquoi la sentence Philippines/Chine 2016 a jugé illégale la transformation de récifs en îles artificielles — cela ne crée aucun droit maritime."},
    {q:"Qu'est-ce que le 'patrimoine commun de l'humanité' dans UNCLOS ?",opts:["Un programme de tourisme maritime","Principe selon lequel les fonds marins au-delà des plateaux continentaux appartiennent à toute l'humanité — ni État ni particulier ne peut en revendiquer la souveraineté","Un traité de pêche","Un article de la Charte des Nations Unies"],correct:1,expl:"Patrimoine commun de l'humanité (UNCLOS Art.136) = principe fondamental pour la Zone (fonds marins au-delà des plateaux). Aucun État ne peut revendiquer la souveraineté. Les ressources sont gérées par l'ISA au profit de toute l'humanité. Les recettes de l'exploitation profitent particulièrement aux pays en développement. Concept révolutionnaire en droit international — limite les nationalismes maritimes."},
    {q:"Qu'est-ce que la 'délimitation maritime' entre États côtiers ?",opts:["Un accord commercial","Processus juridique de fixation des frontières maritimes entre États voisins — méthodes : équidistance · équité · négociation · CIJ · TIDM","Une procédure de l'OMI","Un accord douanier"],correct:1,expl:"Délimitation maritime = fixation de la frontière entre les zones maritimes d'États voisins (mer territoriale, ZEE, plateau continental). Méthodes : équidistance (ligne médiane) en principe, mais équité pour cas spéciaux (îles, concavités côtières). Nombreux différends : France/Canada (Saint-Pierre-et-Miquelon), Bangladesh/Myanmar/Inde, Roumanie/Ukraine. Mécanismes : négociation bilatérale, CIJ, TIDM, arbitrage Annexe VII."},
    {q:"Que signifie le fait que les USA n'ont pas ratifié UNCLOS ?",opts:["Ils ne respectent aucune règle maritime","Les USA respectent UNCLOS comme droit coutumier mais ne sont pas liés par les mécanismes contraignants (TIDM, arbitrage) · ils ne contribuent pas à l'ISA","Ils ont leur propre droit maritime","Ils sont exclus des mers internationales"],correct:1,expl:"USA et UNCLOS : les USA ont signé UNCLOS en 1994 mais le Sénat n'a pas ratifié (opposition à la Partie XI sur la Zone). Paradoxe : les USA respectent et appliquent UNCLOS comme droit coutumier international (ZEE, passage en transit, haute mer). Mais ne sont pas liés par TIDM ou arbitrage Annexe VII. Ne contribuent pas à l'ISA. Leur non-ratification affaiblit UNCLOS politiquement."},
    {q:"Qu'est-ce que la 'sentence arbitrale' dans le cadre UNCLOS est-elle contraignante ?",opts:["Non, c'est une recommandation","Oui — juridiquement contraignante mais sans mécanisme d'exécution forcée · un État peut l'ignorer sans sanction automatique","Oui — avec sanctions automatiques de l'ONU","Non — seulement les décisions de la CIJ sont contraignantes"],correct:1,expl:"Sentence arbitrale UNCLOS = juridiquement contraignante selon le droit international. MAIS aucun mécanisme d'exécution forcée n'existe. Si un État refuse d'appliquer : pas de sanction automatique. Les États peuvent saisir le Conseil de Sécurité de l'ONU — mais les membres permanents (dont la Chine) ont un droit de veto. Leçon Philippines/Chine 2016 : une grande puissance peut ignorer une sentence internationale sans conséquence immédiate."},
    {q:"Qu'est-ce que le 'droit de passage inoffensif' dans les eaux archipélagiques ?",opts:["Un droit de pêche","Droit des navires étrangers de traverser les eaux archipélagiques — similaire au passage innocent mais l'État archipel peut désigner des routes spécifiques","Un droit militaire","Un droit commercial exclusif"],correct:1,expl:"Eaux archipélagiques = eaux entre les îles d'un archipel (Indonésie, Philippines, Fidji). Passage archipélagique (UNCLOS Art.53) : les navires ont le droit de passer par les routes et couloirs aériens désignés par l'État archipel. Plus restrictif que la haute mer, mais avec droit de passage garanti. Les sous-marins peuvent passer immergés dans les voies archipélagiques désignées."},
    {q:"Qu'est-ce que l'UNCLOS dit sur la 'piraterie' en haute mer ?",opts:["La piraterie est permise hors des eaux territoriales","La piraterie = actes illicites commis en haute mer par un navire privé · compétence universelle · tout État peut arraisonner, arrêter et juger les pirates","Seul l'État du pavillon peut poursuivre","La piraterie est gérée par l'OMI"],correct:1,expl:"Piraterie (UNCLOS Art.101-107) = actes illicites de violence, détention ou déprédation commis par un navire privé en haute mer. Compétence UNIVERSELLE : n'importe quel État peut arraisonner, arrêter et juger les pirates (exception au principe d'exclusivité du pavillon). Fondement légal des opérations anti-piraterie (UE NavFor Atalanta, OTAN, Coalition). Terrorisme maritime = différent (sous convention SUA 1988)."},
  ],
  en:[
    {q:"What is the 'baseline' in UNCLOS law?",opts:["Average sea level","Line from which all maritime zones are measured — generally the low-water line · can be a straight baseline (archipelagos)","The boundary between EEZ and high seas","A state's official coastline"],correct:1,expl:"Baseline = fundamental reference for measuring all maritime zones (territorial sea, contiguous zone, EEZ, continental shelf). Normally = low-water mark. Exception: straight baselines (archipelagos, highly irregular coasts — Norway, Indonesia). Baseline points marked on nautical charts. All zone measurements (12+24+200 miles) start from the baseline."},
    {q:"What is 'transit passage' in international straits?",opts:["Simplified innocent passage","Right of continuous and expeditious passage through straits used for international navigation — submarines may pass submerged","A paid commercial passage","A right reserved for riparian states"],correct:1,expl:"Transit passage (UNCLOS Art.37-44) = special regime for international straits (Malacca, Gibraltar, Hormuz, Bab-el-Mandeb). Different from innocent passage: submarines may pass SUBMERGED, military aircraft may overfly. Riparian state cannot suspend transit passage. Major strategic importance for world navies."},
    {q:"What is the 'Commission on the Limits of the Continental Shelf' (CLCS)?",opts:["A maritime jurisdiction","Scientific expert commission created by UNCLOS to validate continental shelf extension claims beyond 200 miles","An IMO body","An arbitral tribunal"],correct:1,expl:"CLCS = Commission on the Limits of the Continental Shelf. Scientific body created by UNCLOS Annex II. Examines requests for continental shelf extension beyond 200 miles (up to 350 miles max). States have 10 years after ratification to submit claims. Examples: France, Australia, Canada, Russia submitted claims for the Arctic. Does not settle disputes — scientifically validates claims."},
    {q:"What is 'the Area' in UNCLOS law?",opts:["The EEZ","The seabed and its subsoil beyond the continental shelf — 'common heritage of mankind' managed by the International Seabed Authority","The high seas","The continental shelf"],correct:1,expl:"The Area = seabed and subsoil beyond continental shelves. Regime created by UNCLOS Part XI. Designated 'common heritage of mankind' = neither states nor individuals can claim sovereignty. Managed by the International Seabed Authority (ISA, Kingston). Contains vast mineral resources (polymetallic nodules, hydrothermal sulfides)."},
    {q:"What is the 'right of hot pursuit' under UNCLOS?",opts:["A commercial right","Right of a coastal state to pursue a foreign vessel on the high seas that violated its laws in its waters — immediate and continuous pursuit required","A military right","An IMO right"],correct:1,expl:"Hot pursuit (UNCLOS Art.111) = right of pursuit on the high seas. Conditions: pursuit begins IN waters under jurisdiction (internal waters, territorial sea, EEZ), it is immediate and continuous (no interruption), it ceases if vessel enters third-state waters. Stop signals must be sent. Audio/visual evidence required. Legal basis for high-seas interceptions."},
    {q:"What is the International Seabed Authority (ISA)?",opts:["A maritime tribunal","International organization created by UNCLOS managing Area resources — issues deep-sea mining exploration and exploitation licenses","An IMO body","A maritime development fund"],correct:1,expl:"ISA = International Seabed Authority. Seat: Kingston, Jamaica. Created by UNCLOS Part XI. Role: regulate exploration and exploitation of mineral resources of the seabed beyond continental shelves. Issues exploration contracts to companies (Contractor). Revenue shared with developing countries. 168 members."},
    {q:"What does UNCLOS say about a coastal state's 'rights over wrecks'?",opts:["A commercial salvage right","Depending on the zone, the coastal state may have variable rights over wrecks — EEZ: limited rights · territorial waters: extensive rights · high seas: freedom of salvage","Coastal state has no rights over wrecks","Only the flag state has rights"],correct:1,expl:"Wrecks and UNCLOS: depends on zone. Internal waters/territorial sea = full coastal state sovereignty (can compel refloating). EEZ = pollution rights but limited wreck rights. High seas = freedom of salvage (subject to flag state rights). Nairobi Convention (2007) on removal of wrecks = complements UNCLOS for hazardous wrecks."},
    {q:"What is the 'right of visit' on the high seas?",opts:["A tourism right","Exceptional right of a warship to board a foreign vessel on the high seas — limited to specific cases (piracy, slavery, drugs)","A port right","A commercial right"],correct:1,expl:"Right of visit (UNCLOS Art.110) = exception to flag state exclusivity. A warship may board a foreign vessel on the high seas ONLY if: suspicion of piracy, suspicion of human trafficking, suspicion of drug trafficking, unauthorized broadcasting, stateless vessel. If suspicion unconfirmed: compensation to boarded vessel. Legal basis for anti-piracy operations (NATO, EU Navfor)."},
    {q:"What does UNCLOS say about 'artificial islands'?",opts:["They automatically create an EEZ","They do not generate a territorial sea, EEZ or continental shelf — only a safety zone of 500 meters","They have the same rights as a natural island","They belong to IMO"],correct:1,expl:"Artificial islands (UNCLOS Art.60): an artificial island, installation or structure built by a state in its EEZ does NOT generate a territorial sea, EEZ or continental shelf. Only a safety zone of maximum 500 meters can be established. That's why the Philippines/China 2016 award found illegal the transformation of reefs into artificial islands — it creates no maritime rights."},
    {q:"What is the 'common heritage of mankind' in UNCLOS?",opts:["A maritime tourism program","Principle that the seabed beyond continental shelves belongs to all humanity — no state or individual can claim sovereignty","A fishing treaty","A UN Charter article"],correct:1,expl:"Common heritage of mankind (UNCLOS Art.136) = fundamental principle for the Area (seabed beyond shelves). No state can claim sovereignty. Resources managed by ISA for the benefit of all humanity. Exploitation revenues particularly benefit developing countries. Revolutionary concept in international law — limits maritime nationalisms."},
    {q:"What is 'maritime delimitation' between coastal states?",opts:["A commercial agreement","Legal process of establishing maritime boundaries between neighboring states — methods: equidistance · equity · negotiation · ICJ · ITLOS","An IMO procedure","A customs agreement"],correct:1,expl:"Maritime delimitation = establishing the boundary between neighboring states' maritime zones (territorial sea, EEZ, continental shelf). Methods: equidistance (median line) in principle, but equity for special cases (islands, coastal concavities). Many disputes: France/Canada (St Pierre), Bangladesh/Myanmar/India, Romania/Ukraine. Mechanisms: bilateral negotiation, ICJ, ITLOS, Annex VII arbitration."},
    {q:"What does the USA's non-ratification of UNCLOS mean?",opts:["They respect no maritime rules","USA respects UNCLOS as customary law but is not bound by binding mechanisms (ITLOS, arbitration) · does not contribute to ISA","They have their own maritime law","They are excluded from international seas"],correct:1,expl:"USA and UNCLOS: USA signed UNCLOS in 1994 but Senate has not ratified (opposition to Part XI on the Area). Paradox: USA respects and applies UNCLOS as customary international law (EEZ, transit passage, high seas). But not bound by ITLOS or Annex VII arbitration. Does not contribute to ISA. Non-ratification politically weakens UNCLOS."},
    {q:"Is an UNCLOS arbitral award binding?",opts:["No, it's a recommendation","Yes — legally binding but without forced enforcement mechanism · a state can ignore it without automatic sanction","Yes — with automatic UN sanctions","No — only ICJ decisions are binding"],correct:1,expl:"UNCLOS arbitral award = legally binding under international law. BUT no forced enforcement mechanism exists. If a state refuses to comply: no automatic sanction. States can go to UN Security Council — but permanent members (including China) have veto power. Lesson Philippines/China 2016: a major power can ignore an international award without immediate consequence."},
    {q:"What is the 'right of archipelagic sea lanes passage'?",opts:["A fishing right","Right of foreign vessels to pass through archipelagic waters — similar to innocent passage but archipelago state can designate specific routes","A military right","An exclusive commercial right"],correct:1,expl:"Archipelagic waters = waters between islands of an archipelago (Indonesia, Philippines, Fiji). Archipelagic sea lanes passage (UNCLOS Art.53): vessels have the right to pass through routes and air corridors designated by the archipelago state. More restrictive than high seas, but with guaranteed right of passage. Submarines may pass submerged in designated archipelagic sea lanes."},
    {q:"What does UNCLOS say about 'piracy' on the high seas?",opts:["Piracy is permitted beyond territorial waters","Piracy = illegal acts on the high seas by a private vessel · universal jurisdiction · any state can board, arrest and prosecute pirates","Only the flag state can prosecute","Piracy is managed by IMO"],correct:1,expl:"Piracy (UNCLOS Art.101-107) = illegal acts of violence, detention or depredation committed by a private vessel on the high seas. UNIVERSAL jurisdiction: any state can board, arrest and prosecute pirates (exception to flag exclusivity). Legal basis for anti-piracy operations (EU NavFor Atalanta, NATO, Coalition). Maritime terrorism = different (under SUA Convention 1988)."},
  ],
  es:[
    {q:"¿Qué es la 'línea de base' en el derecho CONVEMAR?",opts:["El nivel medio del mar","Línea desde la que se miden todas las zonas marítimas — generalmente la línea de bajamar · puede ser una línea de base recta (archipiélagos)","El límite entre ZEE y alta mar","La costa oficial de un Estado"],correct:1,expl:"Línea de base = referencia fundamental para medir todas las zonas marítimas (mar territorial, zona contigua, ZEE, plataforma continental). Normalmente = línea de bajamar. Excepción: líneas de base rectas (archipiélagos, costas muy irregulares — Noruega, Indonesia). Puntos de base marcados en las cartas náuticas. Desde la línea de base comienza el cómputo de las 12+24+200 millas."},
    {q:"¿Qué es el 'paso en tránsito' en los estrechos internacionales?",opts:["El paso inocente simplificado","Derecho de paso continuo y rápido en los estrechos utilizados para la navegación internacional — los submarinos pueden pasar sumergidos","Un paso comercial de pago","Un derecho reservado a los Estados ribereños"],correct:1,expl:"Paso en tránsito (CONVEMAR Art.37-44) = régimen especial para los estrechos internacionales (Malaca, Gibraltar, Ormuz, Bab el-Mandeb). Diferente del paso inocente: los submarinos pueden pasar SUMERGIDOS, los aviones militares pueden sobrevolar. El Estado ribereño no puede suspender el paso en tránsito. Gran importancia estratégica para las marinas militares mundiales."},
    {q:"¿Qué es la 'Comisión de Límites de la Plataforma Continental' (CLPC)?",opts:["Una jurisdicción marítima","Comisión de expertos científicos creada por CONVEMAR para validar las reclamaciones de extensión de la plataforma continental más allá de 200 millas","Un organismo de la OMI","Un tribunal arbitral"],correct:1,expl:"CLPC = Comisión de Límites de la Plataforma Continental. Órgano científico creado por CONVEMAR Anexo II. Examina las solicitudes de extensión de la plataforma continental más allá de 200 millas (hasta 350 millas máx). Los Estados tienen 10 años tras la ratificación para presentar sus reclamaciones. No resuelve controversias — valida científicamente las reclamaciones."},
    {q:"¿Qué es la 'Zona' (Area) en el derecho CONVEMAR?",opts:["La ZEE","Los fondos marinos y su subsuelo más allá de la plataforma continental — 'patrimonio común de la humanidad' gestionado por la Autoridad Internacional de los Fondos Marinos","La alta mar","La plataforma continental"],correct:1,expl:"La Zona = fondos marinos y su subsuelo más allá de las plataformas continentales. Régimen creado por CONVEMAR Parte XI. Denominada 'patrimonio común de la humanidad' = ni los Estados ni los particulares pueden reclamar soberanía. Gestionada por la Autoridad Internacional de los Fondos Marinos (AIFM, Kingston). Contiene enormes recursos minerales."},
    {q:"¿Qué es el 'derecho de persecución en alta mar' (hot pursuit) según CONVEMAR?",opts:["Un derecho comercial","Derecho de un Estado ribereño a perseguir en alta mar a un buque extranjero que ha violado sus leyes en sus aguas — persecución inmediata y continua obligatoria","Un derecho militar","Un derecho de la OMI"],correct:1,expl:"Persecución en alta mar (CONVEMAR Art.111) = derecho de persecución. Condiciones: la persecución comienza EN las aguas bajo jurisdicción, es inmediata y continua (sin interrupción), cesa si el buque entra en aguas de un tercer Estado. Deben enviarse señales de parada. Base legal de las intercepciones en alta mar."},
    {q:"¿Qué es la Autoridad Internacional de los Fondos Marinos (AIFM)?",opts:["Un tribunal marítimo","Organización internacional creada por CONVEMAR que gestiona los recursos de la Zona — otorga licencias de exploración y explotación minera de los fondos marinos","Un organismo de la OMI","Un fondo de desarrollo marítimo"],correct:1,expl:"AIFM = Autoridad Internacional de los Fondos Marinos. Sede: Kingston, Jamaica. Creada por CONVEMAR Parte XI. Función: regular la exploración y explotación de los recursos minerales de los fondos marinos más allá de las plataformas continentales. Otorga contratos de exploración a empresas. Los ingresos se comparten con los países en desarrollo. 168 miembros."},
    {q:"¿Qué dice CONVEMAR sobre los 'derechos del Estado ribereño sobre los pecios'?",opts:["Un derecho comercial de recuperación","Según la zona, el Estado ribereño puede tener derechos variables sobre los pecios — ZEE: derechos limitados · aguas territoriales: derechos amplios · alta mar: libertad de recuperación","El Estado ribereño no tiene ningún derecho sobre los pecios","Solo el Estado pabellón tiene derechos"],correct:1,expl:"Pecios y CONVEMAR: depende de la zona. Aguas interiores/mar territorial = soberanía total del Estado ribereño. ZEE = derechos sobre la contaminación pero derechos limitados sobre el pecio. Alta mar = libertad de recuperación. Convenio de Nairobi (2007) sobre extracción de pecios = complementa CONVEMAR para los pecios peligrosos."},
    {q:"¿Qué es el 'derecho de visita' en alta mar?",opts:["Un derecho turístico","Derecho excepcional de un buque de guerra de abordar a un buque extranjero sospechoso en alta mar — limitado a casos precisos (piratería, esclavitud, drogas)","Un derecho portuario","Un derecho comercial"],correct:1,expl:"Derecho de visita (CONVEMAR Art.110) = excepción al principio de exclusividad del pabellón. Un buque de guerra puede abordar a un buque extranjero en alta mar SOLO si: sospecha de piratería, sospecha de trata de personas, sospecha de tráfico de estupefacientes, emisiones no autorizadas, buque sin nacionalidad. Si la sospecha no se confirma: indemnización al buque abordado."},
    {q:"¿Qué dice CONVEMAR sobre las 'islas artificiales'?",opts:["Crean automáticamente una ZEE","No generan mar territorial, ZEE ni plataforma continental — solo una zona de seguridad de 500 metros","Tienen los mismos derechos que una isla natural","Pertenecen a la OMI"],correct:1,expl:"Islas artificiales (CONVEMAR Art.60): una isla artificial, instalación o estructura construida por un Estado en su ZEE NO genera mar territorial, ZEE ni plataforma continental. Solo puede establecerse una zona de seguridad de 500 metros máximo. Por eso el laudo Filipinas/China 2016 declaró ilegal la transformación de arrecifes en islas artificiales — no crea ningún derecho marítimo."},
    {q:"¿Qué es el 'patrimonio común de la humanidad' en CONVEMAR?",opts:["Un programa de turismo marítimo","Principio según el cual los fondos marinos más allá de las plataformas continentales pertenecen a toda la humanidad — ni Estado ni particular puede reclamar soberanía","Un tratado de pesca","Un artículo de la Carta de las Naciones Unidas"],correct:1,expl:"Patrimonio común de la humanidad (CONVEMAR Art.136) = principio fundamental para la Zona. Ningún Estado puede reclamar soberanía. Los recursos son gestionados por la AIFM en beneficio de toda la humanidad. Los ingresos de la explotación benefician especialmente a los países en desarrollo. Concepto revolucionario en el derecho internacional."},
    {q:"¿Qué es la 'delimitación marítima' entre Estados ribereños?",opts:["Un acuerdo comercial","Proceso jurídico de fijación de las fronteras marítimas entre Estados vecinos — métodos: equidistancia · equidad · negociación · CIJ · TIDM","Un procedimiento de la OMI","Un acuerdo aduanero"],correct:1,expl:"Delimitación marítima = fijación de la frontera entre las zonas marítimas de Estados vecinos (mar territorial, ZEE, plataforma continental). Métodos: equidistancia (línea mediana) en principio, pero equidad para casos especiales. Numerosas controversias en todo el mundo. Mecanismos: negociación bilateral, CIJ, TIDM, arbitraje Anexo VII."},
    {q:"¿Qué significa que EE.UU. no haya ratificado CONVEMAR?",opts:["No respetan ninguna norma marítima","EE.UU. respeta CONVEMAR como derecho consuetudinario pero no está vinculado por los mecanismos vinculantes (TIDM, arbitraje) · no contribuye a la AIFM","Tienen su propio derecho marítimo","Están excluidos de los mares internacionales"],correct:1,expl:"EE.UU. y CONVEMAR: EE.UU. firmó CONVEMAR en 1994 pero el Senado no ha ratificado (oposición a la Parte XI sobre la Zona). Paradoja: EE.UU. respeta y aplica CONVEMAR como derecho internacional consuetudinario. Pero no está vinculado por el TIDM ni el arbitraje del Anexo VII. No contribuye a la AIFM. Su no ratificación debilita políticamente CONVEMAR."},
    {q:"¿Es vinculante un laudo arbitral en el marco CONVEMAR?",opts:["No, es una recomendación","Sí — jurídicamente vinculante pero sin mecanismo de ejecución forzosa · un Estado puede ignorarlo sin sanción automática","Sí — con sanciones automáticas de la ONU","No — solo las decisiones de la CIJ son vinculantes"],correct:1,expl:"Laudo arbitral CONVEMAR = jurídicamente vinculante según el derecho internacional. PERO no existe ningún mecanismo de ejecución forzosa. Si un Estado se niega a cumplir: no hay sanción automática. Los Estados pueden acudir al Consejo de Seguridad de la ONU — pero los miembros permanentes (incluida China) tienen derecho de veto. Lección Filipinas/China 2016."},
    {q:"¿Qué es el 'derecho de paso de las vías marítimas archipelágicas'?",opts:["Un derecho de pesca","Derecho de los buques extranjeros a pasar por las aguas archipelágicas — similar al paso inocente pero el Estado archipiélago puede designar rutas específicas","Un derecho militar","Un derecho comercial exclusivo"],correct:1,expl:"Aguas archipelágicas = aguas entre las islas de un archipiélago (Indonesia, Filipinas, Fiyi). Paso por vías marítimas archipelágicas (CONVEMAR Art.53): los buques tienen derecho a pasar por las rutas y corredores aéreos designados por el Estado archipiélago. Los submarinos pueden pasar sumergidos en las vías archipelágicas designadas."},
    {q:"¿Qué dice CONVEMAR sobre la 'piratería' en alta mar?",opts:["La piratería está permitida fuera de las aguas territoriales","Piratería = actos ilícitos cometidos en alta mar por un buque privado · competencia universal · cualquier Estado puede abordar, detener y juzgar a los piratas","Solo el Estado pabellón puede enjuiciar","La piratería está gestionada por la OMI"],correct:1,expl:"Piratería (CONVEMAR Art.101-107) = actos ilícitos de violencia, detención o depredación cometidos por un buque privado en alta mar. Competencia UNIVERSAL: cualquier Estado puede abordar, detener y juzgar a los piratas (excepción al principio de exclusividad del pabellón). Base legal de las operaciones antipiratería (EU NavFor Atalanta, OTAN, Coalición)."},
  ],
  pt:[
    {q:"O que é a 'linha de base' no direito UNCLOS?",opts:["O nível médio do mar","Linha a partir da qual se medem todas as zonas marítimas — geralmente a linha de baixa-mar · pode ser uma linha de base reta (arquipélagos)","O limite entre ZEE e alto mar","A costa oficial de um Estado"],correct:1,expl:"Linha de base = referência fundamental para medir todas as zonas marítimas (mar territorial, zona contígua, ZEE, plataforma continental). Normalmente = linha de baixa-mar. Exceção: linhas de base retas (arquipélagos, costas muito irregulares — Noruega, Indonésia). Pontos de base marcados nas cartas náuticas. Todas as medições de zona (12+24+200 milhas) começam a partir da linha de base."},
    {q:"O que é a 'passagem em trânsito' nos estreitos internacionais?",opts:["A passagem inocente simplificada","Direito de passagem contínua e expedita nos estreitos utilizados para a navegação internacional — os submarinos podem passar submersos","Uma passagem comercial paga","Um direito reservado aos estados ribeirinhos"],correct:1,expl:"Passagem em trânsito (UNCLOS Art.37-44) = regime especial para os estreitos internacionais (Malaca, Gibraltar, Ormuz, Bab-el-Mandeb). Diferente da passagem inocente: os submarinos podem passar SUBMERSOS, os aviões militares podem sobrevoar. O estado ribeirinho não pode suspender a passagem em trânsito. Grande importância estratégica para as marinhas militares mundiais."},
    {q:"O que é a 'Comissão de Limites da Plataforma Continental' (CLPC)?",opts:["Uma jurisdição marítima","Comissão de peritos científicos criada pela UNCLOS para validar as reivindicações de extensão da plataforma continental além das 200 milhas","Um organismo da IMO","Um tribunal arbitral"],correct:1,expl:"CLPC = Comissão de Limites da Plataforma Continental. Órgão científico criado pela UNCLOS Anexo II. Examina os pedidos de extensão da plataforma continental além das 200 milhas (até 350 milhas máx). Os estados têm 10 anos após a ratificação para apresentar as suas reivindicações. Não resolve controvérsias — valida cientificamente as reivindicações."},
    {q:"O que é a 'Área' (Area) no direito UNCLOS?",opts:["A ZEE","Os fundos marinhos e o seu subsolo além da plataforma continental — 'patrimônio comum da humanidade' gerido pela Autoridade Internacional dos Fundos Marinhos","O alto mar","A plataforma continental"],correct:1,expl:"A Área = fundos marinhos e subsolo além das plataformas continentais. Regime criado pela UNCLOS Parte XI. Designada 'patrimônio comum da humanidade' = nem estados nem particulares podem reivindicar soberania. Gerida pela Autoridade Internacional dos Fundos Marinhos (AIFM, Kingston). Contém vastos recursos minerais."},
    {q:"O que é o 'direito de perseguição em alto mar' (hot pursuit) segundo a UNCLOS?",opts:["Um direito comercial","Direito de um Estado costeiro de perseguir em alto mar um navio estrangeiro que violou as suas leis nas suas águas — perseguição imediata e contínua obrigatória","Um direito militar","Um direito da IMO"],correct:1,expl:"Perseguição em alto mar (UNCLOS Art.111) = direito de perseguição. Condições: a perseguição começa NAS águas sob jurisdição, é imediata e contínua (sem interrupção), cessa se o navio entrar nas águas de um terceiro estado. Sinais de paragem devem ser enviados. Base legal das interceções em alto mar."},
    {q:"O que é a Autoridade Internacional dos Fundos Marinhos (AIFM)?",opts:["Um tribunal marítimo","Organização internacional criada pela UNCLOS que gere os recursos da Área — emite licenças de exploração e exploração mineira dos fundos marinhos","Um organismo da IMO","Um fundo de desenvolvimento marítimo"],correct:1,expl:"AIFM = Autoridade Internacional dos Fundos Marinhos. Sede: Kingston, Jamaica. Criada pela UNCLOS Parte XI. Função: regular a exploração e aproveitamento dos recursos minerais dos fundos marinhos além das plataformas continentais. Emite contratos de exploração a empresas. As receitas são partilhadas com os países em desenvolvimento. 168 membros."},
    {q:"O que diz a UNCLOS sobre os 'direitos do Estado costeiro sobre os naufrágios'?",opts:["Um direito comercial de recuperação","Dependendo da zona, o Estado costeiro pode ter direitos variáveis sobre os naufrágios — ZEE: direitos limitados · águas territoriais: direitos extensos · alto mar: liberdade de recuperação","O Estado costeiro não tem direitos sobre os naufrágios","Apenas o Estado de bandeira tem direitos"],correct:1,expl:"Naufrágios e UNCLOS: depende da zona. Águas interiores/mar territorial = soberania total do Estado costeiro. ZEE = direitos sobre a poluição mas direitos limitados sobre o naufrágio. Alto mar = liberdade de recuperação. Convenção de Nairóbi (2007) sobre remoção de naufrágios = complementa a UNCLOS para naufrágios perigosos."},
    {q:"O que é o 'direito de visita' em alto mar?",opts:["Um direito de turismo","Direito excecional de um navio de guerra de abordar um navio estrangeiro suspeito em alto mar — limitado a casos precisos (pirataria, escravatura, droga)","Um direito portuário","Um direito comercial"],correct:1,expl:"Direito de visita (UNCLOS Art.110) = exceção ao princípio da exclusividade da bandeira. Um navio de guerra pode abordar um navio estrangeiro em alto mar APENAS se: suspeita de pirataria, suspeita de tráfico de pessoas, suspeita de tráfico de estupefacientes, difusão não autorizada, navio sem nacionalidade. Se suspeita não confirmada: indemnização ao navio abordado."},
    {q:"O que diz a UNCLOS sobre as 'ilhas artificiais'?",opts:["Criam automaticamente uma ZEE","Não geram mar territorial, ZEE nem plataforma continental — apenas uma zona de segurança de 500 metros","Têm os mesmos direitos que uma ilha natural","Pertencem à IMO"],correct:1,expl:"Ilhas artificiais (UNCLOS Art.60): uma ilha artificial, instalação ou estrutura construída por um estado na sua ZEE NÃO gera mar territorial, ZEE ou plataforma continental. Apenas pode ser estabelecida uma zona de segurança de 500 metros máximo. Por isso a sentença Filipinas/China 2016 declarou ilegal a transformação de recifes em ilhas artificiais — não cria nenhum direito marítimo."},
    {q:"O que é o 'patrimônio comum da humanidade' na UNCLOS?",opts:["Um programa de turismo marítimo","Princípio segundo o qual os fundos marinhos além das plataformas continentais pertencem a toda a humanidade — nenhum estado ou particular pode reivindicar soberania","Um tratado de pesca","Um artigo da Carta das Nações Unidas"],correct:1,expl:"Patrimônio comum da humanidade (UNCLOS Art.136) = princípio fundamental para a Área. Nenhum estado pode reivindicar soberania. Os recursos são geridos pela AIFM em benefício de toda a humanidade. As receitas da exploração beneficiam particularmente os países em desenvolvimento. Conceito revolucionário no direito internacional."},
    {q:"O que é a 'delimitação marítima' entre estados costeiros?",opts:["Um acordo comercial","Processo jurídico de fixação das fronteiras marítimas entre estados vizinhos — métodos: equidistância · equidade · negociação · TIJ · TIDM","Um procedimento da IMO","Um acordo aduaneiro"],correct:1,expl:"Delimitação marítima = fixação da fronteira entre as zonas marítimas de estados vizinhos (mar territorial, ZEE, plataforma continental). Métodos: equidistância (linha mediana) em princípio, mas equidade para casos especiais. Numerosas controvérsias em todo o mundo. Mecanismos: negociação bilateral, TIJ, TIDM, arbitragem Anexo VII."},
    {q:"O que significa os EUA não terem ratificado a UNCLOS?",opts:["Não respeitam nenhuma regra marítima","Os EUA respeitam a UNCLOS como direito consuetudinário mas não estão vinculados pelos mecanismos vinculativos (TIDM, arbitragem) · não contribuem para a AIFM","Têm o seu próprio direito marítimo","Estão excluídos dos mares internacionais"],correct:1,expl:"EUA e UNCLOS: os EUA assinaram a UNCLOS em 1994 mas o Senado não ratificou (oposição à Parte XI sobre a Área). Paradoxo: os EUA respeitam e aplicam a UNCLOS como direito internacional consuetudinário. Mas não estão vinculados pelo TIDM nem pela arbitragem do Anexo VII. Não contribuem para a AIFM. A sua não ratificação enfraquece politicamente a UNCLOS."},
    {q:"Uma sentença arbitral no âmbito da UNCLOS é vinculativa?",opts:["Não, é uma recomendação","Sim — juridicamente vinculativa mas sem mecanismo de execução forçada · um estado pode ignorá-la sem sanção automática","Sim — com sanções automáticas da ONU","Não — apenas as decisões do TIJ são vinculativas"],correct:1,expl:"Sentença arbitral UNCLOS = juridicamente vinculativa segundo o direito internacional. MAS não existe nenhum mecanismo de execução forçada. Se um estado se recusar a cumprir: não há sanção automática. Os estados podem recorrer ao Conselho de Segurança da ONU — mas os membros permanentes (incluindo a China) têm direito de veto. Lição Filipinas/China 2016."},
    {q:"O que é o 'direito de passagem das vias marítimas arquipelágicas'?",opts:["Um direito de pesca","Direito dos navios estrangeiros de passar pelas águas arquipelágicas — similar à passagem inocente mas o estado arquipélago pode designar rotas específicas","Um direito militar","Um direito comercial exclusivo"],correct:1,expl:"Águas arquipelágicas = águas entre as ilhas de um arquipélago (Indonésia, Filipinas, Fiji). Passagem pelas vias marítimas arquipelágicas (UNCLOS Art.53): os navios têm direito de passar pelas rotas e corredores aéreos designados pelo estado arquipélago. Os submarinos podem passar submersos nas vias arquipelágicas designadas."},
    {q:"O que diz a UNCLOS sobre a 'pirataria' em alto mar?",opts:["A pirataria é permitida fora das águas territoriais","Pirataria = atos ilícitos cometidos em alto mar por um navio privado · competência universal · qualquer estado pode abordar, prender e julgar os piratas","Apenas o estado de bandeira pode processar","A pirataria é gerida pela IMO"],correct:1,expl:"Pirataria (UNCLOS Art.101-107) = atos ilícitos de violência, detenção ou depredação cometidos por um navio privado em alto mar. Competência UNIVERSAL: qualquer estado pode abordar, prender e julgar piratas (exceção ao princípio da exclusividade da bandeira). Base legal das operações antipirataria (EU NavFor Atalanta, NATO, Coligação)."},
  ],
};

function QuestionBank({ lang }) {
  const [cur,setCur]=useState(0);const [sel,setSel]=useState(null);const [answered,setAnswered]=useState(false);const [score,setScore]=useState(0);const [done,setDone]=useState(false);
  const questions=BANK[lang]||BANK.fr;
  const [shuffled]=useState(()=>questions.map(shuffleQuestionOptions));
  const q=shuffled[cur];const isOk=sel===q.correct;
  const pick=i=>{if(answered)return;setSel(i);setAnswered(true);if(i===q.correct)setScore(s=>s+1);};
  const next=()=>{if(cur<questions.length-1){setCur(c=>c+1);setSel(null);setAnswered(false);}else setDone(true);};
  if(done)return(<div style={{textAlign:"center",padding:"20px 0"}}><div style={{fontSize:48}}>{score>=12?"🏆":score>=8?"🎖️":"📚"}</div><div style={{fontFamily:"'Cinzel',serif",fontSize:20,color:C.white,margin:"8px 0 4px"}}>{score}/{questions.length}</div><div style={{fontSize:14,color:C.gold2}}>{Math.round(score/questions.length*100)}%</div></div>);
  return(<div>
    <div style={{display:"flex",justifyContent:"space-between",marginBottom:10}}><div style={{fontSize:10,color:C.muted}}>{cur+1}/{questions.length}</div><div style={{fontSize:12,color:C.gold2,fontWeight:700}}>✓ {score}</div></div>
    <div style={{height:3,background:"rgba(255,255,255,0.08)",borderRadius:3,marginBottom:12,overflow:"hidden"}}><div style={{height:"100%",width:`${(cur/questions.length)*100}%`,background:`linear-gradient(90deg,${C.blue2},${C.green})`}}/></div>
    <div style={{fontSize:13,fontWeight:700,color:C.white,lineHeight:1.5,marginBottom:12}}>{q.q}</div>
    <div style={{display:"flex",flexDirection:"column",gap:8,marginBottom:10}}>
      {q.opts.map((opt,i)=>{let bg="rgba(255,255,255,0.05)",bd="rgba(255,255,255,0.1)";if(answered){if(i===q.correct){bg="rgba(30,138,74,0.2)";bd=C.green;}else if(i===sel){bg="rgba(192,57,43,0.2)";bd=C.red;}}return<button key={i} onClick={()=>pick(i)} style={{padding:"10px 12px",borderRadius:12,background:bg,border:`1.5px solid ${bd}`,color:C.muted,fontSize:12,textAlign:"left",cursor:answered?"default":"pointer",lineHeight:1.4}}>{opt}</button>;})}
    </div>
    {answered&&<><div style={{padding:"10px 12px",borderRadius:10,marginBottom:10,background:isOk?"rgba(30,138,74,0.12)":"rgba(192,57,43,0.1)",border:`1px solid ${isOk?C.green:C.red}44`,fontSize:11,color:C.white,lineHeight:1.6}}>{q.expl}</div>
    <button onClick={next} style={{width:"100%",padding:"11px 0",border:"none",borderRadius:12,background:`linear-gradient(135deg,${C.blue2},${C.green})`,fontFamily:"'Cinzel',serif",fontSize:12,fontWeight:700,letterSpacing:2,color:C.white,cursor:"pointer"}}>{cur<questions.length-1?(lang==="fr"?"SUIVANT →":lang==="en"?"NEXT →":lang==="es"?"SIGUIENTE →":"PRÓXIMO →"):(lang==="fr"?"TERMINER":lang==="en"?"FINISH":lang==="es"?"TERMINAR":"TERMINAR")}</button></>}
  </div>);
}

function Stars(){const s=Array.from({length:16},()=>({x:Math.random()*100,y:Math.random()*100,sz:Math.random()>0.7?2:1.5,dur:2+Math.random()*4,delay:Math.random()*6}));return(<><div style={{position:"fixed",inset:0,pointerEvents:"none",zIndex:0}}>{s.map((st,i)=><div key={i} style={{position:"absolute",left:`${st.x}%`,top:`${st.y}%`,width:st.sz,height:st.sz,borderRadius:"50%",background:"white",opacity:0,animation:`tw ${st.dur}s ease-in-out ${st.delay}s infinite`}}/>)}</div><style>{`@keyframes tw{0%,100%{opacity:0}50%{opacity:0.35}}@keyframes fadeUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}@keyframes correctPop{0%{transform:scale(0.85)}60%{transform:scale(1.1)}100%{transform:scale(1)}}@keyframes wrongShake{0%,100%{transform:translateX(0)}25%{transform:translateX(-5px)}75%{transform:translateX(5px)}}`}</style></>);}
function Card({children,style={}}){return<div style={{background:"rgba(13,31,60,0.75)",border:`1px solid ${C.border}`,borderRadius:18,padding:"16px",...style}}>{children}</div>;}
function GLine(){return<div style={{height:1,margin:"14px 0",background:`linear-gradient(90deg,transparent,${C.blue2}33,${C.green}33,transparent)`}}/>;}
function SL({icon,text,color}){return<div style={{display:"flex",alignItems:"center",gap:10,margin:"20px 0 12px"}}><span style={{fontSize:20}}>{icon}</span><div style={{fontFamily:"'Cinzel',serif",fontSize:12,fontWeight:700,color:color||C.gold,letterSpacing:2}}>{text}</div><div style={{flex:1,height:1,background:`linear-gradient(90deg,${color||C.gold}44,transparent)`}}/></div>;}

function QuizComp({questions,t,onComplete}){
  const [shuffled]=useState(()=>questions.map(shuffleQuestionOptions));
  const [cur,setCur]=useState(0);const [sel,setSel]=useState(null);const [answered,setAnswered]=useState(false);const [score,setScore]=useState(0);const [answers,setAnswers]=useState([]);const [done,setDone]=useState(false);
  const q=shuffled[cur];const isOk=sel===q.correct;
  const pick=i=>{if(answered)return;setSel(i);setAnswered(true);if(i===q.correct)setScore(s=>s+1);setAnswers(a=>[...a,{i,ok:i===q.correct}]);};
  const next=()=>{if(cur<questions.length-1){setCur(c=>c+1);setSel(null);setAnswered(false);}else{setDone(true);onComplete(score+(isOk?1:0));}};
  if(done){const fs=score;const pct=Math.round(fs/questions.length*100);const xp=fs>=4?200:fs===3?120:60;return(<Card style={{textAlign:"center"}}><div style={{fontSize:52,marginBottom:8}}>{pct===100?"🏆":pct>=80?"🎖️":"📚"}</div><div style={{fontFamily:"'Cinzel',serif",fontSize:28,fontWeight:900,color:C.white,marginBottom:4}}>{fs}/{questions.length}</div><div style={{display:"inline-block",marginTop:8,padding:"6px 16px",borderRadius:20,background:"rgba(201,146,42,0.15)",border:`1px solid ${C.gold}44`,fontSize:14,color:C.gold2,fontWeight:700}}>+{xp} {t.xp} ⭐</div><GLine/><div style={{display:"flex",justifyContent:"center",gap:8,marginTop:8}}>{answers.map((a,i)=><div key={i} style={{width:32,height:32,borderRadius:"50%",background:a.ok?C.green:C.red,display:"flex",alignItems:"center",justifyContent:"center",fontSize:14,color:C.white}}>{a.ok?"✓":"✗"}</div>)}</div></Card>);}
  return(<Card style={{border:`1px solid ${C.blue2}33`}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}><div style={{fontSize:11,letterSpacing:3,color:C.blue2,fontFamily:"'Cinzel',serif"}}>{t.quiz}</div><div style={{fontSize:12,color:C.muted}}>{t.question} {cur+1} {t.ofQ} {questions.length}</div></div><div style={{display:"flex",gap:6,marginBottom:16}}>{questions.map((_,i)=><div key={i} style={{flex:1,height:3,borderRadius:3,background:i<cur?(answers[i]?.ok?C.green:C.red):i===cur?C.blue2:"rgba(255,255,255,0.1)"}}/>)}</div><div style={{fontSize:14,fontWeight:700,color:C.white,lineHeight:1.5,marginBottom:16}}>{q.q}</div><div style={{display:"flex",flexDirection:"column",gap:10,marginBottom:14}}>{q.opts.map((opt,i)=>{let bg="rgba(255,255,255,0.05)",bd="rgba(255,255,255,0.1)",anim="none";if(answered){if(i===q.correct){bg="rgba(30,138,74,0.2)";bd=C.green;anim="correctPop 0.4s ease";}else if(i===sel){bg="rgba(192,57,43,0.2)";bd=C.red;anim="wrongShake 0.4s ease";}}return<button key={i} onClick={()=>pick(i)} style={{padding:"12px 14px",borderRadius:14,background:bg,border:`1.5px solid ${bd}`,color:answered&&(i===q.correct||i===sel)?C.white:C.muted,fontSize:13,textAlign:"left",cursor:answered?"default":"pointer",animation:anim,display:"flex",alignItems:"center",gap:10,lineHeight:1.4}}><div style={{width:26,height:26,borderRadius:"50%",flexShrink:0,background:answered&&i===q.correct?C.green:answered&&i===sel?C.red:"rgba(255,255,255,0.1)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:12,fontWeight:700,color:C.white}}>{answered&&i===q.correct?"✓":answered&&i===sel?"✗":String.fromCharCode(65+i)}</div><span>{opt}</span></button>;})} </div>{answered&&<div style={{padding:"12px 14px",borderRadius:12,marginBottom:14,background:isOk?"rgba(30,138,74,0.12)":"rgba(192,57,43,0.1)",border:`1px solid ${isOk?C.green:C.red}44`,animation:"fadeUp 0.4s ease"}}><div style={{fontSize:12,fontWeight:700,marginBottom:4,color:isOk?C.green:C.red}}>{isOk?t.correct:t.wrong}</div><div style={{fontSize:11,color:C.muted,fontWeight:600,marginBottom:2}}>{t.expl}</div><div style={{fontSize:12,color:C.white,lineHeight:1.6}}>{q.expl}</div></div>}{answered&&<button onClick={next} style={{width:"100%",padding:"14px 0",border:"none",borderRadius:14,background:`linear-gradient(135deg,${C.blue2},${C.gold})`,fontFamily:"'Cinzel',serif",fontSize:13,fontWeight:700,letterSpacing:2,color:C.white,cursor:"pointer"}}>{cur<questions.length-1?t.next:t.finish}</button>}</Card>);
}

